const RETRYABLE_STATUSES = new Set([408, 429, 500, 502, 503, 504]);
const MAX_ATTEMPTS = 3;

/**
 * Determines whether an outbound HTTP request should be retried.
 *
 * @param {number} status - The HTTP status code received (or 0/undefined on network error).
 * @param {number} attempt - The number of attempts already made (1 after the first call).
 * @param {number} [maxAttempts=3] - Maximum number of allowed attempts.
 * @returns {boolean} Whether the call should be retried.
 */
export function shouldRetry(status, attempt, maxAttempts = MAX_ATTEMPTS) {
  if (attempt >= maxAttempts) {
    return false;
  }

  // Network errors / connection drops typically yield status 0 or undefined
  if (!status) {
    return true;
  }

  return RETRYABLE_STATUSES.has(status);
}

export default shouldRetry;
