/**
 * Validates a Turkish Republic Identity Number (TCKN).
 *
 * @param {string|number} s
 * @returns {boolean}
 * @throws {Error}
 */
export function validateTckn(s) {
  const str = String(s);

  if (!/^\d{11}$/.test(str)) {
    throw new Error('TCKN 11 haneli olmalıdır.');
  }

  if (str.startsWith('0')) {
    throw new Error('TCKN 0 ile başlayamaz.');
  }

  const digits = str.split('').map(Number);

  const oddSum = digits[0] + digits[2] + digits[4] + digits[6] + digits[8];
  const evenSum = digits[1] + digits[3] + digits[5] + digits[7];

  const digit10 = ((oddSum * 7) - evenSum) % 10;
  const normalizedDigit10 = (digit10 + 10) % 10;

  if (normalizedDigit10 !== digits[9]) {
    throw new Error('Geçersiz TCKN.');
  }

  const first10Sum = digits.slice(0, 10).reduce((acc, curr) => acc + curr, 0);
  if (first10Sum % 10 !== digits[10]) {
    throw new Error('Geçersiz TCKN.');
  }

  return true;
}
