/**
 * Normalizes a Turkish phone number into standard E.164 format (+905XXXXXXXXX).
 *
 * @param {string|number} s
 * @returns {string|null} Normalized phone number, or null if invalid.
 */
export function telefonNormalize(s) {
  if (s == null) {
    return null;
  }

  let cleaned = String(s).replace(/\D/g, '');

  if (cleaned.startsWith('0090')) {
    cleaned = cleaned.slice(4);
  } else if (cleaned.startsWith('90')) {
    cleaned = cleaned.slice(2);
  } else if (cleaned.startsWith('0')) {
    cleaned = cleaned.slice(1);
  }

  // Türkiye için geçerli bir cep/alan kodu numarası 10 haneli olmalı ve 5 ile başlamalı (özellikle cep için)
  // ya da genel 10 haneli standart numara olmalı.
  if (cleaned.length === 10) {
    return `+90${cleaned}`;
  }

  return null;
}

export default telefonNormalize;
