/**
 * Calculates the retry delay in milliseconds from GitHub API response headers.
 * GitHub sends a standard `retry-after` header in seconds.
 *
 * @param {Record<string, string | undefined>} headers
 * @returns {number | null} Retry delay in milliseconds, or null if header is missing or invalid.
 */
export function githubRetryDelayMs(headers) {
  if (!headers || headers['retry-after'] === undefined) {
    return null;
  }

  const seconds = Number(headers['retry-after']);
  if (!Number.isFinite(seconds) || seconds < 0) {
    return null;
  }

  return Math.round(seconds * 1000);
}
