```js
/**
 * Calculates the retry delay in milliseconds after receiving a 429 response from Paraşüt.
 *
 * @param {Record<string, string | undefined>} headers - Response headers with lowercase keys.
 * @returns {number} Milliseconds to wait before retrying.
 */
export function parasutRetryDelayMs(headers) {
  const retryAfter = headers?.['retry-after'];

  if (retryAfter !== undefined && retryAfter !== null) {
    const seconds = Number(retryAfter);
    if (!Number.isNaN(seconds) && seconds >= 0) {
      return seconds * 1000;
    }

    const dateMs = Date.parse(retryAfter);
    if (!Number.isNaN(dateMs)) {
      return Math.max(0, dateMs - Date.now());
    }
  }

  const reset = headers?.['x-ratelimit-reset'] ?? headers?.['x-rate-limit-reset'];
  if (reset !== undefined && reset !== null) {
    const resetVal = Number(reset);
    if (!Number.isNaN(resetVal) && resetVal >= 0) {
      // If reset value is a Unix timestamp in seconds (epoch > year 2001)
      if (resetVal > 1_000_000_000) {
        return Math.max(0, resetVal * 1000 - Date.now());
      }
      // Otherwise treated as delta seconds
      return resetVal * 1000;
    }
  }

  // Default fallback delay
  return 1000;
}
