const CUTOFF_HOUR = 14;

/**
 * Determines whether an order placed at the given date/time missed the same-day shipping cut-off.
 * Same-day cutoff is 14:00 (2:00 PM) local time, Monday through Friday.
 * Weekend orders automatically miss the same-day cutoff.
 *
 * @param {Date} date - The order timestamp.
 * @returns {boolean} True if the cutoff was missed, false otherwise.
 */
export function isAfterCutoff(date) {
  const d = new Date(date);
  const day = d.getDay();

  // 0 is Sunday, 6 is Saturday
  if (day === 0 || day === 6) {
    return true;
  }

  const hours = d.getHours();
  const minutes = d.getMinutes();
  const seconds = d.getSeconds();
  const ms = d.getMilliseconds();

  return (
    hours > CUTOFF_HOUR ||
    (hours === CUTOFF_HOUR && (minutes > 0 || seconds > 0 || ms > 0))
  );
}

export default isAfterCutoff;
