```js
/**
 * Calculates total VAT (KDV) in kuruş from an array of net amounts in kuruş.
 *
 * Turkish tax regulations calculate VAT on the sum of net amounts rather than
 * summing individually rounded VAT lines, avoiding cumulative rounding errors.
 *
 * @param {number[]} lineNets - Line net amounts in kuruş (integers)
 * @param {number} ratePercent - VAT rate percentage (e.g. 1, 10, 20)
 * @returns {number} Total VAT in kuruş (rounded to nearest integer)
 */
