```js
/**
 * Kullanıcı tarafından girilen telefon numarasını normalize eder.
 * Türkiye telefon numarası formatına uygun olarak başında ülke koduyla birlikte
 * 12 haneli uluslararası formatta ("+905XXXXXXXXX") döndürür.
 *
 * @param {string} s - Normalize edilecek ham telefon numarası
 * @returns {string|null} Normalize edilmiş telefon numarası ya da geçersizse null
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') {
    return null;
  }

  // Yalnızca rakamları al
  let digits = s.replace(/\D/g, '');

  // 0090... -> 90...
  if (digits.startsWith('0090')) {
    digits = digits.slice(2);
  }

  // 05XX... -> 905XX... (11 hane ise baştaki 0'ı atıp 90 ekle)
  if (digits.startsWith('0') && digits.length === 11) {
    digits = '90' + digits.slice(1);
  }

  // 5XX... -> 905XX... (10 hane ise başına 90 ekle)
  if (digits.length === 10 && digits.startsWith('5')) {
    digits = '90' + digits;
  }

  // Geçerli Türkiye cep/sabit telefon numarası: 90 ile başlar ve toplam 12 hanelidir
  if (digits.length === 12 && digits.startsWith('90')) {
    return `+${digits}`;
  }

  return null;
}

export default telefonNormalize;
