```js
const BUSINESS_TIMEZONE = 'Europe/Istanbul';

/**
 * Parses a date-only string (YYYY-MM-DD) into a Date object representing
 * the start of that day in the business timezone.
 *
 * @param {string} s - Date string in YYYY-MM-DD format
 * @returns {Date} Date instance corresponding to the start of the day in the business timezone
 */
export function parseDeliveryDate(s) {
  if (!s || typeof s !== 'string') {
    throw new TypeError('Invalid date string');
  }

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s.trim());
  if (!match) {
    throw new RangeError(`Invalid date format, expected YYYY-MM-DD: "${s}"`);
  }

  const [, yearStr, monthStr, dayStr] = match;
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);

  const utcGuess = new Date(Date.UTC(year, month - 1, day, 0, 0, 0));

  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: BUSINESS_TIMEZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23'
  });

  const getTzParts = (d) => {
    const parts = dtf.formatToParts(d);
    const map = {};
    for (const { type, value } of parts) {
      map[type] = value;
    }
    return {
      year: Number(map.year),
      month: Number(map.month),
      day: Number(map.day),
      hour: Number(map.hour),
      minute: Number(map.minute),
      second: Number(map.second)
    };
  };

  const tzParts = getTzParts(utcGuess);
  const tzAsUtc = Date.UTC(
    tzParts.year,
    tzParts.month - 1,
    tzParts.day,
    tzParts.hour,
    tzParts.minute,
    tzParts.second
  );

  const offset = tzAsUtc - utcGuess.getTime();
  const targetUtcTime = utcGuess.getTime() - offset;
  const result = new Date(targetUtcTime);

  const finalParts = getTzParts(result);
  const finalAsUtc = Date.UTC(
    finalParts.year,
    finalParts.month - 1,
    finalParts.day,
    finalParts.hour,
    finalParts.minute,
    finalParts.second
  );
  const finalOffset = finalAsUtc - result.getTime();

  if (finalOffset !== offset) {
    return new Date(utcGuess.getTime() - finalOffset);
  }

  return result;
}
```

