export function formatTutar(tutar) {
  const kurusValue =
    typeof tutar === 'object' && tutar !== null && 'amount' in tutar
      ? tutar.amount
      : tutar;

  const raw = BigInt(kurusValue);
  const isNegative = raw < 0n;
  const abs = isNegative ? -raw : raw;

  const liras = abs / 100n;
  const kurus = abs % 100n;

  const liraFormatted = liras.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const kurusFormatted = kurus.toString().padStart(2, '0');

  const sign = isNegative ? '-' : '';

  return `${sign}${liraFormatted},${kurusFormatted} TL`;
}
