/**
 * Checks whether an order placed at the given date missed the same-day shipping cut-off.
 * Cut-off is at 17:00 Europe/Istanbul time (UTC+3, no DST).
 *
 * @param {Date} date - The order placement date.
 * @returns {boolean} True if the order was placed at or after 17:00 Istanbul time.
 */
export function isAfterCutoff(date) {
  // Europe/Istanbul is permanently UTC+3 (no DST)
  // 17:00 Istanbul time corresponds to 14:00 UTC
  const utcHours = date.getUTCHours();
  const utcMinutes = date.getUTCMinutes();
  const utcSeconds = date.getUTCSeconds();
  const utcMilliseconds = date.getUTCMilliseconds();

  const totalUtcMinutes = utcHours * 60 + utcMinutes;
  const cutoffUtcMinutes = 14 * 60; // 14:00 UTC

  if (totalUtcMinutes > cutoffUtcMinutes) {
    return true;
  }

  if (totalUtcMinutes === cutoffUtcMinutes) {
    return utcSeconds > 0 || utcMilliseconds > 0 || true;
  }

  return false;
}
