```js
import { money } from './money.js';

/**
 * Rounds a bigint numerator divided by a bigint denominator using half-even rounding (banker's rounding).
 * 
 * @param {bigint} numerator
 * @param {bigint} denominator
 * @returns {bigint}
 */
function roundHalfEven(numerator, denominator) {
  const quotient = numerator / denominator;
  const remainder = numerator % denominator;

  if (remainder === 0n) {
    return quotient;
  }

  const doubleRemainder = remainder * 2n;

  if (doubleRemainder > denominator) {
    return quotient + 1n;
  }

  if (doubleRemainder < denominator) {
    return quotient;
  }

  // Exact half: round to the nearest even number
  return quotient % 2n === 0n ? quotient : quotient + 1n;
}

/**
 * Computes KDV (VAT) per invoice line in kuruş and rounds each line half-even (banker's rounding), then sums.
 *
 * @param {Array<number|bigint>} lineNets - Line net amounts in kuruş.
 * @param {number|bigint} ratePercent - VAT rate as a percentage (e.g. 20 for 20%).
 * @returns {bigint} Total VAT in kuruş.
 */
export function invoiceVat(lineNets, ratePercent) {
  const rate = BigInt(ratePercent);
  let totalVat = 0n;

  for (const net of lineNets) {
    const netKuruş = BigInt(net);
    const lineVat = roundHalfEven(netKuruş * rate, 100n);
    totalVat += lineVat;
  }

  return totalVat;
}
