/**
 * Formats an integer amount of US cents into USD currency string (e.g. $1,234.50).
 *
 * @param {number|bigint} cents
 * @returns {string}
 */
export function formatUsd(cents) {
  const isNegative = cents < 0n || cents < 0;
  const absCents = typeof cents === 'bigint'
    ? (cents < 0n ? -cents : cents)
    : BigInt(Math.abs(cents));

  const dollars = absCents / 100n;
  const remainingCents = absCents % 100n;

  const dollarsFormatted = dollars.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  const centsFormatted = remainingCents.toString().padStart(2, '0');

  return `${isNegative ? '-' : ''}$${dollarsFormatted}.${centsFormatted}`;
}
