 *
 * @template T
 * @param {T[]} array - The array to split.
 * @param {number} size - The chunk size.
 * @returns {T[][]} An array of chunks.
 */
export function parcala(array, size) {
  if (!Array.isArray(array)) {
    throw new AppError('INVALID_INPUT', 'HATA-GIRDI: dizi parametresi bir dizi olmalıdır');
