/**
 * Validates a Turkish Republic Identification Number (TCKN).
 *
 * @param {string|number} s
 * @returns {boolean}
 */
export function validateTckn(s) {
  const str = String(s);

  if (!/^\d{11}$/.test(str)) {
    throw new Error('TCKN 11 haneli olmalıdır.');
  }

  if (str.startsWith('0')) {
    throw new Error('TCKN 0 ile başlayamaz.');
  }

  const digits = str.split('').map(Number);

  const sumOdd = digits[0] + digits[2] + digits[4] + digits[6] + digits[8];
  const sumEven = digits[1] + digits[3] + digits[5] + digits[7];

  const tenthDigit = ((sumOdd * 7) - sumEven) % 10;
  const normalizedTenth = (tenthDigit + 10) % 10;

  if (normalizedTenth !== digits[9]) {
    throw new Error('Geçersiz TCKN.');
  }

  const sumFirstTen = digits.slice(0, 10).reduce((acc, d) => acc + d, 0);
  const eleventhDigit = sumFirstTen % 10;

  if (eleventhDigit !== digits[10]) {
    throw new Error('Geçersiz TCKN.');
  }

  return true;
}
