/**
 * Normalizes a Turkish phone number into standard E.164 format (+905XXXXXXXXX).
 *
 * @param {string} s - Input phone number string
 * @returns {string} Normalized phone number
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Telefon numarası metin olmalıdır.');
  }

  let cleaned = s.replace(/\D/g, '');

  if (cleaned.startsWith('0090')) {
    cleaned = cleaned.slice(4);
  } else if (cleaned.startsWith('90')) {
    cleaned = cleaned.slice(2);
  }

  if (cleaned.startsWith('0')) {
    cleaned = cleaned.slice(1);
  }

  if (cleaned.length !== 10 || !cleaned.startsWith('5')) {
    throw new Error('Geçersiz telefon numarası.');
  }

  return `+90${cleaned}`;
}
