function roundHalfEven(n) {
  const sign = Math.sign(n) || 1;
  const abs = Math.abs(n);
  const floor = Math.floor(abs);
  const diff = abs - floor;
  const eps = 1e-9;

  let rounded;
  if (Math.abs(diff - 0.5) < eps) {
    rounded = floor % 2 === 0 ? floor : floor + 1;
  } else {
    rounded = Math.round(abs);
  }

  return sign * rounded;
}

export function invoiceVat(lineNets, ratePercent) {
  return lineNets.reduce((total, lineNet) => {
    const lineVat = (lineNet * ratePercent) / 100;
    return total + roundHalfEven(lineVat);
  }, 0);
}
