/**
 * Validates a Turkish Republic Identity Number (TCKN).
 *
 * @param {string} s
 * @returns {boolean}
 * @throws {Error}
 */
export function validateTckn(s) {
  const str = String(s ?? '');

  if (!/^[1-9]\d{10}$/.test(str)) {
    throw new Error('HATA-TCKN: geçersiz kimlik numarası');
  }

  const digits = str.split('').map(Number);

  const oddSum = digits[0] + digits[2] + digits[4] + digits[6] + digits[8];
  const evenSum = digits[1] + digits[3] + digits[5] + digits[7];

  const tenth = ((oddSum * 7) - evenSum) % 10;
  const normalizedTenth = (tenth + 10) % 10;

  if (digits[9] !== normalizedTenth) {
    throw new Error('HATA-TCKN: geçersiz kimlik numarası');
  }

  const firstTenSum = digits.slice(0, 10).reduce((acc, curr) => acc + curr, 0);
  if (digits[10] !== (firstTenSum % 10)) {
    throw new Error('HATA-TCKN: geçersiz kimlik numarası');
  }

  return true;
}
```

