const RETRYABLE_STATUS_CODES = new Set([
  408, // Request Timeout
  429, // Too Many Requests
  500, // Internal Server Error
  502, // Bad Gateway
  503, // Service Unavailable
  504, // Gateway Timeout
]);

const DEFAULT_MAX_ATTEMPTS = 3;

/**
 * Determines whether an outbound HTTP request should be retried.
 *
 * @param {number} status - The HTTP response status code (or 0 / undefined if network error).
 * @param {number} attempt - The number of attempts already made (1 after the first call).
 * @param {number} [maxAttempts=DEFAULT_MAX_ATTEMPTS] - Maximum allowed attempts.
 * @returns {boolean} Whether to retry the request.
 */
export function shouldRetry(status, attempt, maxAttempts = DEFAULT_MAX_ATTEMPTS) {
  if (attempt >= maxAttempts) {
    return false;
  }

  // Network or connection errors typically represented as status 0 or falsy
  if (!status || status === 0) {
    return true;
  }

  return RETRYABLE_STATUS_CODES.has(status);
}

export default shouldRetry;
```

