/**
 * Kullanıcının girdiği telefon numarasını standart veritabanı biçimine (+905XXXXXXXXX) dönüştürür.
 * 
 * @param {string} s - Kullanıcı tarafından girilen telefon numarası
 * @returns {string|null} Normalleştirilmiş telefon numarası veya geçersiz ise null
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') return null;

  // Sadece rakamları ayıkla
  let digits = s.replace(/\D/g, '');

  // Başındaki 0090 veya 90 kodunu kaldır
  if (digits.startsWith('0090')) {
    digits = digits.slice(4);
  } else if (digits.startsWith('90')) {
    digits = digits.slice(2);
  }

  // Başındaki tek sıfırı kaldır (örn. 0532 -> 532)
  if (digits.startsWith('0')) {
    digits = digits.slice(1);
  }

  // Türkiye için geçerli cep telefonu formatı: 5 ile başlayan 10 hane
  if (digits.length === 10 && digits.startsWith('5')) {
    return `+90${digits}`;
  }

  return null;
}

export default telefonNormalize;
