const DEFAULT_DELAY_MS = 60000;

/**
 * Calculates how many milliseconds to wait after a 429 response from the Paraşüt API.
 *
 * @param {Record<string, string>} headers - Plain headers object with lower-case keys.
 * @returns {number} Milliseconds to wait before retrying.
 */
export function parasutRetryDelayMs(headers) {
  if (!headers) {
    return DEFAULT_DELAY_MS;
  }

  const retryAfter = headers['retry-after'];
  if (retryAfter !== undefined && retryAfter !== null) {
    const seconds = Number(retryAfter);
    if (!Number.isNaN(seconds) && seconds >= 0) {
      return seconds * 1000;
    }

    const dateParsed = Date.parse(retryAfter);
    if (!Number.isNaN(dateParsed)) {
      const diff = dateParsed - Date.now();
      return diff > 0 ? diff : 0;
    }
  }

  const resetTime = headers['x-rate-limit-reset'] ?? headers['x-ratelimit-reset'];
  if (resetTime !== undefined && resetTime !== null) {
    const resetSeconds = Number(resetTime);
    if (!Number.isNaN(resetSeconds) && resetSeconds >= 0) {
      // If it's a UNIX epoch timestamp in seconds
      if (resetSeconds > 1000000000) {
        const diff = resetSeconds * 1000 - Date.now();
        return diff > 0 ? diff : 0;
      }
      return resetSeconds * 1000;
    }
  }

  return DEFAULT_DELAY_MS;
}

export default parasutRetryDelayMs;
