 *
 * @param {string} s - Input phone number string
 * @returns {string|null} Normalized phone number or null if invalid
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') {
    return null;
  }

  // Sadece rakamları al
  let digits = s.replace(/\D/g, '');

  // 0090 ile başlıyorsa 00'ı at
  if (digits.startsWith('0090')) {
    digits = digits.slice(2);
  }

  // 90 ile başlıyorsa ve 12 haneliyse (+905XXXXXXXXX)
  if (digits.length === 12 && digits.startsWith('90')) {
    digits = digits.slice(2);
  }

  // Başında 0 varsa kaldır (05XXXXXXXXX -> 5XXXXXXXXX)
  if (digits.length === 11 && digits.startsWith('0')) {
    digits = digits.slice(1);
  }

  // Türkiye için geçerli 10 haneli numara (5XX XXX XX XX)
  if (digits.length === 10 && digits.startsWith('5')) {
    return `+90${digits}`;
  }

  return null;
}

