/**
 * Parses a date-only string (e.g. "YYYY-MM-DD") into a Date object
 * representing midnight in the local/business timezone.
 *
 * @param {string} s - Date-only string in "YYYY-MM-DD" format
 * @returns {Date}
 */
export function parseDeliveryDate(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Expected date string');
  }

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s.trim());
  if (!match) {
    throw new Error(`Invalid delivery date format: ${s}`);
  }

  const [, year, month, day] = match;
  return new Date(Number(year), Number(month) - 1, Number(day));
}
