/**
 * Formats an amount in kuruş to a display string (e.g. 1.234,50 TL).
 * Supports integer (number or bigint) or Money object.
 *
 * @param {number | bigint | { amount: bigint | number }} tutar
 * @returns {string}
 */
export function formatTutar(tutar) {
  const kurusBigInt =
    typeof tutar === 'object' && tutar !== null && 'amount' in tutar
      ? BigInt(tutar.amount)
      : BigInt(tutar);

  const isNegative = kurusBigInt < 0n;
  const absKurus = isNegative ? -kurusBigInt : kurusBigInt;

  const lira = absKurus / 100n;
  const kurusRem = absKurus % 100n;

  const formattedLira = lira
    .toString()
    .replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const formattedKurus = kurusRem.toString().padStart(2, '0');

  const sign = isNegative ? '-' : '';

  return `${sign}${formattedLira},${formattedKurus} TL`;
}
