/**
 * Rounds a number to the nearest integer using half-even (banker's rounding).
 *
 * @param {number} value
 * @returns {bigint}
 */
function roundHalfEven(value) {
  const floor = Math.floor(value);
  const diff = value - floor;

  if (diff > 0.5) {
    return BigInt(floor + 1);
  }
  if (diff < 0.5) {
    return BigInt(floor);
  }
  return BigInt(floor % 2 === 0 ? floor : floor + 1);
}

/**
 * Computes the total VAT (KDV) in kuruş for given invoice line net amounts.
 * KDV is computed per line in kuruş and rounded using banker's rounding (half-even), then summed.
 *
 * @param {Array<number|bigint>} lineNets - Line net amounts in kuruş
 * @param {number} ratePercent - VAT rate as a percentage (e.g. 20 for 20%)
 * @returns {bigint} Total VAT amount in kuruş
 */
export function invoiceVat(lineNets, ratePercent) {
  let totalVat = 0n;

  for (const net of lineNets) {
    const netAmount = typeof net === "bigint" ? Number(net) : net;
    const vatLine = (netAmount * ratePercent) / 100;
    totalVat += roundHalfEven(vatLine);
  }

  return totalVat;
}
