export function parcala(dizi, n) {
  if (!Array.isArray(dizi)) {
    throw new AppError('INVALID_INPUT', 'HATA-GIRDI: dizi parametresi bir dizi olmalıdır');
  }

  if (typeof n !== 'number' || n <= 0 || !Number.isInteger(n)) {
