export function validateTckn(s) {
  const str = String(s ?? '');

  if (!/^\d{11}$/.test(str)) {
    throw new Error('T.C. Kimlik Numarası 11 haneli olmalıdır.');
  }

  if (str.startsWith('0')) {
    throw new Error('T.C. Kimlik Numarası 0 ile başlayamaz.');
  }

  const digits = str.split('').map(Number);

  const oddSum = digits[0] + digits[2] + digits[4] + digits[6] + digits[8];
  const evenSum = digits[1] + digits[3] + digits[5] + digits[7];

  const tenthDigit = ((oddSum * 7) - evenSum) % 10;
  const normalizedTenth = (tenthDigit + 10) % 10;

  if (normalizedTenth !== digits[9]) {
    throw new Error('Geçersiz T.C. Kimlik Numarası.');
  }

  const firstTenSum = digits.slice(0, 10).reduce((sum, d) => sum + d, 0);
  if (firstTenSum % 10 !== digits[10]) {
    throw new Error('Geçersiz T.C. Kimlik Numarası.');
  }

  return true;
}
