import { money } from './money.js';

/**
 * Sums a list of Money values.
 *
 * @param {Array<{ amount: bigint, currency: string }>} values
 * @param {string} [defaultCurrency='TRY']
 * @returns {{ amount: bigint, currency: string }}
 */
export function sumMoney(values, defaultCurrency = 'TRY') {
  if (!values || values.length === 0) {
    return money(0n, defaultCurrency);
  }

  const currency = values[0].currency;
  let totalAmount = 0n;

  for (const item of values) {
    if (item.currency !== currency) {
      throw new TypeError(`Cannot sum different currencies: ${currency} and ${item.currency}`);
    }
    totalAmount += BigInt(item.amount);
  }

  return money(totalAmount, currency);
}
