/**
 * Validates a Turkish Republic Identity Number (TCKN).
 *
 * @param {string} s
 * @returns {boolean}
 */
export function validateTckn(s) {
  const str = String(s);

  if (!/^\d{11}$/.test(str) || str.startsWith('0')) {
    throw new Error('HATA-TCKN: geçersiz kimlik numarası');
  }

  const digits = str.split('').map(Number);

  const sumOdd = digits[0] + digits[2] + digits[4] + digits[6] + digits[8];
  const sumEven = digits[1] + digits[3] + digits[5] + digits[7];

  const digit10 = (sumOdd * 7 - sumEven) % 10;
  const normalizedDigit10 = (digit10 + 10) % 10;

  if (normalizedDigit10 !== digits[9]) {
    throw new Error('HATA-TCKN: geçersiz kimlik numarası');
  }

  const sumFirst10 = digits.slice(0, 10).reduce((acc, curr) => acc + curr, 0);
  if (sumFirst10 % 10 !== digits[10]) {
    throw new Error('HATA-TCKN: geçersiz kimlik numarası');
  }

  return true;
}
