/**
 * Parses a key-value string separated by semicolons into an object.
 *
 * @param {string} s - The input string (e.g. "a=1;b=two;c=")
 * @returns {Record<string, string>}
 */
export function parseKv(s) {
  const result = {};
  if (!s) return result;

  const segments = s.split(';');
  for (const segment of segments) {
    if (!segment) continue;

    const eqIndex = segment.indexOf('=');
    if (eqIndex === -1) {
      result[segment] = '';
    } else {
      const key = segment.slice(0, eqIndex);
      const value = segment.slice(eqIndex + 1);
      result[key] = value;
    }
  }

  return result;
}
