import { money } from './money.js';

/**
 * Sums a list of money values (all expected to share the same currency).
 *
 * @param {Array<{ amount: bigint, currency: string }>} values
 * @returns {{ amount: bigint, currency: string }}
 */
export function sumMoney(values) {
  if (!values || values.length === 0) {
    throw new Error('Cannot sum an empty list of money values without a currency');
  }

  const { currency } = values[0];
  let total = 0n;

  for (const item of values) {
    if (item.currency !== currency) {
      throw new TypeError(`Currency mismatch: expected ${currency}, got ${item.currency}`);
    }
    total += BigInt(item.amount);
  }

  return money(total, currency);
}
