/**
 * Rounds a number to the nearest integer using half-even rounding (banker's rounding).
 * @param {number} n
 * @returns {number}
 */
function roundHalfEven(n) {
  const floor = Math.floor(n);
  const diff = n - floor;

  if (diff > 0.5) {
    return floor + 1;
  }
  if (diff < 0.5) {
    return floor;
  }
  return floor % 2 === 0 ? floor : floor + 1;
}

/**
 * Computes total KDV (VAT) for an invoice.
 * VAT is computed per line in kuruş, rounded with half-even rounding, then summed.
 *
 * @param {number[]} lineNets - Line net amounts in kuruş (integers)
 * @param {number} ratePercent - VAT rate percentage (e.g. 20 for 20%)
 * @returns {number} Total VAT in kuruş
 */
export function invoiceVat(lineNets, ratePercent) {
  return lineNets.reduce((totalVat, lineNet) => {
    const rawVat = (lineNet * ratePercent) / 100;
    return totalVat + roundHalfEven(rawVat);
  }, 0);
}
