/**
 * Kullanıcının girdiği telefon numarasını E.164 formatına (+905XXXXXXXXX) dönüştürür.
 * @param {string} s
 * @returns {string}
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Telefon numarası metin olmalıdır');
  }

  const digits = s.replace(/\D/g, '');

  if (digits.length === 10 && digits.startsWith('5')) {
    return `+90${digits}`;
  }

  if (digits.length === 11 && digits.startsWith('05')) {
    return `+90${digits.slice(1)}`;
  }

  if (digits.length === 12 && digits.startsWith('905')) {
    return `+${digits}`;
  }

  throw new Error('HATA-TEL: Geçersiz telefon numarası formatı');
}
