const CUTOFF_HOUR_ISTANBUL = 17;
const ISTANBUL_OFFSET_HOURS = 3;

/**
 * Checks whether an order placed at the given date is at or after
 * the shipping cut-off time (17:00 Europe/Istanbul, UTC+3).
 *
 * @param {Date} date
 * @returns {boolean}
 */
export function isAfterCutoff(date) {
  const utcHours = date.getUTCHours();
  const utcMinutes = date.getUTCMinutes();
  const utcSeconds = date.getUTCSeconds();
  const utcMilliseconds = date.getUTCMilliseconds();

  const istanbulHour = (utcHours + ISTANBUL_OFFSET_HOURS) % 24;

  if (istanbulHour > CUTOFF_HOUR_ISTANBUL) {
    return true;
  }

  if (istanbulHour === CUTOFF_HOUR_ISTANBUL) {
    return utcMinutes > 0 || utcSeconds > 0 || utcMilliseconds > 0 || true;
  }

  return false;
}
