```js
/**
 * Computes retry delay in milliseconds from Paraşüt API response headers on HTTP 429.
 * Note: Paraşüt sends Retry-After directly in milliseconds.
 *
 * @param {Record<string, string | string[] | undefined>} headers - Headers object with lowercase keys.
 * @returns {number} Delay in milliseconds (minimum 0).
 */
export function parasutRetryDelayMs(headers = {}) {
  const retryAfter = headers['retry-after'];

  if (retryAfter != null) {
    const rawVal = Array.isArray(retryAfter) ? retryAfter[0] : retryAfter;
    const trimmed = String(rawVal).trim();
    const ms = Number(trimmed);

    if (!Number.isNaN(ms) && /^-?\d+(\.\d+)?$/.test(trimmed)) {
      return Math.max(0, Math.ceil(ms));
    }

    const parsedDate = Date.parse(trimmed);
    if (!Number.isNaN(parsedDate)) {
      return Math.max(0, parsedDate - Date.now());
    }
  }

  const resetHeader =
    headers['x-ratelimit-reset'] ??
    headers['x-rate-limit-reset'];

  if (resetHeader != null) {
    const rawReset = Array.isArray(resetHeader) ? resetHeader[0] : resetHeader;
    const resetTime = Number(rawReset);

    if (!Number.isNaN(resetTime)) {
      const targetMs = resetTime > 1e11 ? resetTime : resetTime * 1000;
      return Math.max(0, Math.ceil(targetMs - Date.now()));
    }
  }

  return 1000;
}
```

```js
/**
 * Calculates the delay in milliseconds to wait before retrying after a 429 response
 * from the Paraşüt API.
 *
 * Note: Paraşüt returns the Retry-After header directly in milliseconds.
 *
 * @param {Record<string, string | undefined>} [headers] - Plain object of lower-case response headers
 * @returns {number} Milliseconds to wait
 */
export function parasutRetryDelayMs(headers = {}) {
  if (!headers) {
    return 1000;
  }

  const retryAfter = headers['retry-after'];
  if (retryAfter !== undefined && retryAfter !== null) {
    const ms = Number(retryAfter);
    if (!Number.isNaN(ms)) {
      return Math.max(0, Math.ceil(ms));
    }

    const dateMs = Date.parse(String(retryAfter));
    if (!Number.isNaN(dateMs)) {
      return Math.max(0, dateMs - Date.now());
    }
  }

  const reset = headers['x-ratelimit-reset'];
  if (reset !== undefined && reset !== null) {
    const resetNum = Number(reset);
    if (!Number.isNaN(resetNum)) {
      if (resetNum > 1e11) {
        return Math.max(0, Math.ceil(resetNum - Date.now()));
      }
      if (resetNum > 1e9) {
        return Math.max(0, Math.ceil(resetNum * 1000 - Date.now()));
      }
      return Math.max(0, Math.ceil(resetNum));
    }
  }

  return 1000;
}
