  config.timezone ||
  config.timeZone ||
  config.BUSINESS_TIMEZONE ||
  (config.default && (config.default.TIMEZONE || config.default.timezone || config.default.timeZone)) ||
  'UTC';

/**
 * Parses a "YYYY-MM-DD" date-only string into a Date representing
 * the start of that day in the shop's business timezone.
 *
 * @param {string} s - Date-only string (e.g. "2026-03-01")
 * @returns {Date}
 */
export function parseDeliveryDate(s) {
  const [year, month, day] = s.split('-').map(Number);

  let timestamp = Date.UTC(year, month - 1, day, 0, 0, 0, 0);

  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: TIMEZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });

  for (let i = 0; i < 3; i++) {
    const parts = formatter.formatToParts(new Date(timestamp));
    const values = {};
    for (const { type, value } of parts) {
      values[type] = value;
    }

    const currentYear = Number(values.year);
    const currentMonth = Number(values.month);
    const currentDay = Number(values.day);
    let currentHour = Number(values.hour);
    if (currentHour === 24) currentHour = 0;
    const currentMinute = Number(values.minute);
    const currentSecond = Number(values.second);

    const asUtcTimestamp = Date.UTC(
      currentYear,
      currentMonth - 1,
      currentDay,
      currentHour,
      currentMinute,
      currentSecond
    );

    const targetAsUtc = Date.UTC(year, month - 1, day, 0, 0, 0);
    const diff = targetAsUtc - asUtcTimestamp;

    if (diff === 0) {
      break;
    }
    timestamp += diff;
  }

  return new Date(timestamp);
}
