import { BUSINESS_TIMEZONE } from './timezone.js';

function getTimezoneOffset(timeZone, date) {
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone,
    timeZoneName: 'longOffset',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });

  const parts = formatter.formatToParts(date);
  const tzPart = parts.find((p) => p.type === 'timeZoneName');
  if (!tzPart) return 0;

  const match = tzPart.value.match(/GMT([+-])(\d{1,2}):?(\d{2})?/);
  if (!match) return 0;

  const sign = match[1] === '+' ? 1 : -1;
  const hours = parseInt(match[2], 10);
  const minutes = match[3] ? parseInt(match[3], 10) : 0;
  return sign * (hours * 60 + minutes);
}

/**
 * Parses a date-only string (e.g. "2026-03-01") into a Date
 * representing that day in the business timezone.
 *
 * @param {string} s - Date-only string in YYYY-MM-DD format.
 * @returns {Date} Date corresponding to midnight in the business timezone.
 */
export function parseDeliveryDate(s) {
  const [year, month, day] = s.split('-').map(Number);
  const utcGuess = new Date(Date.UTC(year, month - 1, day, 0, 0, 0));
  const offsetMinutes = getTimezoneOffset(BUSINESS_TIMEZONE, utcGuess);
  return new Date(utcGuess.getTime() - offsetMinutes * 60 * 1000);
}
