import { BUSINESS_TIMEZONE } from './timezone.js';

/**
 * Returns the offset in minutes for a given Date in a specific IANA timezone.
 * offset = timezone_time - UTC_time
 */
function getTimezoneOffset(date, timeZone) {
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });

  const parts = formatter.formatToParts(date);
  const partMap = {};
  for (const { type, value } of parts) {
    partMap[type] = value;
  }

  const asUTC = Date.UTC(
    Number(partMap.year),
    Number(partMap.month) - 1,
    Number(partMap.day),
    Number(partMap.hour) === 24 ? 0 : Number(partMap.hour),
    Number(partMap.minute),
    Number(partMap.second)
  );

  return (asUTC - date.getTime()) / 60000;
}

/**
 * Parses a date-only string like "2026-03-01" into a Date
 * representing the start of that day in the business timezone.
 *
 * @param {string} s - Date string in YYYY-MM-DD format
 * @returns {Date}
 */
export function parseDeliveryDate(s) {
  const [year, month, day] = s.split('-').map(Number);

  // Initial UTC timestamp representing midnight UTC on that date
  const utcTimestamp = Date.UTC(year, month - 1, day, 0, 0, 0);

  // Guess the target time by subtracting the offset at that UTC instant
  let offset = getTimezoneOffset(new Date(utcTimestamp), BUSINESS_TIMEZONE);
  let target = new Date(utcTimestamp - offset * 60000);

  // Recalculate offset at the target time to handle daylight saving boundaries
  const refinedOffset = getTimezoneOffset(target, BUSINESS_TIMEZONE);
  if (refinedOffset !== offset) {
    target = new Date(utcTimestamp - refinedOffset * 60000);
  }

  return target;
}
