import { CUTOFF_HOUR, CUTOFF_MINUTE } from './config.js';

/**
 * Determines whether an order placed at the given date missed the same-day shipping cut-off.
 *
 * @param {Date} date
 * @returns {boolean}
 */
export function isAfterCutoff(date) {
  const cutoffHour = CUTOFF_HOUR ?? 14;
  const cutoffMinute = CUTOFF_MINUTE ?? 0;

  const hours = date.getHours();
  const minutes = date.getMinutes();
  const seconds = date.getSeconds();
  const ms = date.getMilliseconds();

  if (hours > cutoffHour) {
    return true;
  }
  if (hours === cutoffHour) {
    if (minutes > cutoffMinute) {
      return true;
    }
    if (minutes === cutoffMinute && (seconds > 0 || ms > 0)) {
      return true;
    }
  }

  return false;
}
