/**
 * Normalizes a Turkish phone number into standard international format (+90XXXXXXXXXX).
 * 
 * @param {string} s - Raw phone number input
 * @returns {string|null} Normalized phone number or null if invalid
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') {
    return null;
  }

  // Sadece rakamları ve baştaki '+' işaretini koru
  const cleaned = s.trim().replace(/[^\d+]/g, '');

  let digits = cleaned.replace(/\D/g, '');

  // 0090 ile başlıyorsa 00'ı at
  if (digits.startsWith('0090')) {
    digits = digits.slice(2);
  }

  // 90 ile başlıyorsa ve 12 haneli ise (905XXXXXXXXX)
  if (digits.startsWith('90') && digits.length === 12) {
    // Geçerli biçim
  } else if (digits.startsWith('0') && digits.length === 11) {
    // 05XXXXXXXXX -> 905XXXXXXXXX
    digits = '90' + digits.slice(1);
  } else if (digits.length === 10 && digits.startsWith('5')) {
    // 5XXXXXXXXX -> 905XXXXXXXXX
    digits = '90' + digits;
  } else {
    return null;
  }

  // Türkiye için geçerli bir mobil/sabit hat formatı kontrolü (12 hane ve 90 ile başlama)
  if (digits.length === 12 && digits.startsWith('90')) {
    return `+${digits}`;
  }

  return null;
}

export default telefonNormalize;
