import { TIMEZONE } from './config.js';

/**
 * Parses a date-only string (e.g. "YYYY-MM-DD") into a Date object
 * representing midnight at the start of that day in the business timezone.
 *
 * @param {string} s - The date-only string.
 * @returns {Date}
 */
export function parseDeliveryDate(s) {
  const [year, month, day] = s.split('-').map(Number);

  // Approximate UTC timestamp for the target calendar date
  let guess = Date.UTC(year, month - 1, day);

  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: TIMEZONE,
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: 'numeric',
    second: 'numeric',
    hour12: false,
  });

  // Iteratively adjust until the localized representation matches midnight on that date
  for (let i = 0; i < 3; i++) {
    const parts = formatter.formatToParts(new Date(guess));
    const values = {};
    for (const { type, value } of parts) {
      values[type] = parseInt(value, 10);
    }
    if (values.hour === 24) {
      values.hour = 0;
    }

    const currentAsUtc = Date.UTC(
      values.year,
      values.month - 1,
      values.day,
      values.hour,
      values.minute,
      values.second
    );

    const targetAsUtc = Date.UTC(year, month - 1, day, 0, 0, 0);
    const diff = targetAsUtc - currentAsUtc;

    if (diff === 0) {
      break;
    }
    guess += diff;
  }

  return new Date(guess);
}
