/**
 * Normalizes a Turkish phone number into a standard format.
 * Format: +905XXXXXXXXX
 *
 * @param {string} s - Input phone number string
 * @returns {string|null} Normalized phone number or null if invalid
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') {
    return null;
  }

  // Sadece rakamları al
  let cleaned = s.replace(/\D/g, '');

  // Başındaki 0090'ı temizle
  if (cleaned.startsWith('0090')) {
    cleaned = cleaned.slice(4);
  } else if (cleaned.startsWith('90')) {
    // Başındaki 90'ı temizle
    cleaned = cleaned.slice(2);
  }

  // Başındaki 0'ı temizle
  if (cleaned.startsWith('0')) {
    cleaned = cleaned.slice(1);
  }

  // Türkiye için kalan numara 10 haneli ve 5 ile başlamalı
  if (cleaned.length === 10 && cleaned.startsWith('5')) {
    return `+90${cleaned}`;
  }

  return null;
}
