```js
const RETRYABLE_STATUS_CODES = new Set([408, 429, 500, 502, 503, 504]);
const MAX_ATTEMPTS = 3;

/**
 * Determines whether an outbound HTTP request should be retried.
 *
 * @param {number} status - The HTTP response status code (or 0 for network/timeout errors).
 * @param {number} attempt - The number of attempts already made (1 after the first call).
 * @param {number} [maxAttempts=3] - Maximum number of allowed attempts.
 * @returns {boolean}
 */
export function shouldRetry(status, attempt, maxAttempts = MAX_ATTEMPTS) {
  if (attempt >= maxAttempts) {
    return false;
  }

  // Network failures / timeouts often yield status 0 or nullish status
  if (!status || status === 0) {
    return true;
  }

  return RETRYABLE_STATUS_CODES.has(status);
}
