export const BUSINESS_TIMEZONE = 'Europe/Istanbul';

/**
 * Parses a "YYYY-MM-DD" string into a Date object representing
 * the start of that day in the business timezone.
 *
 * @param {string} s - Date string in YYYY-MM-DD format
 * @param {string} [timeZone=BUSINESS_TIMEZONE] - Business timezone
 * @returns {Date}
 */
export function parseDeliveryDate(s, timeZone = BUSINESS_TIMEZONE) {
  if (!s || typeof s !== 'string') {
    throw new TypeError('Expected a date string in YYYY-MM-DD format');
  }

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s.trim());
  if (!match) {
    throw new RangeError(`Invalid date format: "${s}". Expected YYYY-MM-DD`);
  }

  const [, year, month, day] = match;
  const isoLocal = `${year}-${month}-${day}T00:00:00`;

  // Determine timezone offset for the given local datetime
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  });

  // Target local timestamp components
  const targetYear = Number(year);
  const targetMonth = Number(month);
  const targetDay = Number(day);

  // Initial estimate treating local as UTC
  let utcTime = Date.UTC(targetYear, targetMonth - 1, targetDay, 0, 0, 0);

  // Adjust for timezone offset
  const parts = formatter.formatToParts(new Date(utcTime));
  const partMap = {};
  for (const p of parts) {
    partMap[p.type] = p.value;
  }

  const asLocal = Date.UTC(
    Number(partMap.year),
    Number(partMap.month) - 1,
    Number(partMap.day),
    Number(partMap.hour === '24' ? '0' : partMap.hour),
    Number(partMap.minute),
    Number(partMap.second)
  );

  const offset = asLocal - utcTime;
  return new Date(utcTime - offset);
}

export default parseDeliveryDate;
