function roundHalfEven(numerator, denominator) {
  const quotient = numerator / denominator;
  const remainder = numerator % denominator;
  const doubledRemainder = remainder * 2n;

  if (doubledRemainder > denominator) {
    return quotient + 1n;
  }
  if (doubledRemainder < denominator) {
    return quotient;
  }
  return quotient % 2n === 0n ? quotient : quotient + 1n;
}

export function invoiceVat(lineNets, ratePercent) {
  const rateBig = BigInt(ratePercent);
  const total = lineNets.reduce((sum, net) => {
    const netBig = BigInt(net);
    const lineVat = roundHalfEven(netBig * rateBig, 100n);
    return sum + lineVat;
  }, 0n);

  return Number(total);
}
```

