import { AppError } from './errors.js';

/**
 * Formats a money amount given in kuruş (integer/bigint or Money object)
 * into Turkish Lira display format: '1.234,50 TL'.
 *
 * @param {number|bigint|{ amount: bigint|number, currency?: string }} tutar
 * @returns {string}
 */
export function formatTutar(tutar) {
  let kurusVal;

  if (tutar !== null && typeof tutar === 'object' && 'amount' in tutar) {
    kurusVal = tutar.amount;
  } else {
    kurusVal = tutar;
  }

  if (typeof kurusVal === 'number') {
    if (!Number.isInteger(kurusVal)) {
      throw new AppError('INVALID_AMOUNT', 'Tutar tam sayı cinsinden kuruş olmalıdır');
    }
    kurusVal = BigInt(kurusVal);
  } else if (typeof kurusVal !== 'bigint') {
    throw new AppError('INVALID_AMOUNT', 'Geçersiz tutar formatı');
  }

  const isNegative = kurusVal < 0n;
  const abs = isNegative ? -kurusVal : kurusVal;

  const lira = abs / 100n;
  const kurus = abs % 100n;

  const liraStr = lira.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const kurusStr = kurus.toString().padStart(2, '0');
  const prefix = isNegative ? '-' : '';

  return `${prefix}${liraStr},${kurusStr} TL`;
}
