/**
 * Normalizes a Turkish phone number into E.164 format (+905XXXXXXXXX).
 *
 * @param {string} input - Raw phone number string from user input.
 * @returns {string} Normalized E.164 phone number.
 */
export function telefonNormalize(input) {
  if (typeof input !== 'string') {
    throw new AppError('INVALID_PHONE', 'HATA-TEL: geçersiz telefon numarası');
  }

  const cleaned = input.replace(/\D/g, '');

  let digits = cleaned;
  if (digits.startsWith('90')) {
    digits = digits.slice(2);
  } else if (digits.startsWith('0')) {
