/**
 * Normalizes a Turkish phone number into standard international format (+90XXXXXXXXXX).
 * Accepts formats like "0532 123 45 67", "532-123-4567", "+90 532 123 45 67".
 *
 * @param {string} s - Input phone string
 * @returns {string} Normalized phone number (+90XXXXXXXXXX)
 * @throws {Error} When the phone number is invalid
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Telefon numarası metin formatında olmalıdır.');
  }

  // Sadece rakamları ayıkla
  let cleaned = s.replace(/\D/g, '');

  // Başındaki 0090 veya 90 kodunu temizle
  if (cleaned.startsWith('0090')) {
    cleaned = cleaned.slice(4);
  } else if (cleaned.startsWith('90')) {
    cleaned = cleaned.slice(2);
  }

  // Başındaki yerel '0'ı temizle
  if (cleaned.startsWith('0')) {
    cleaned = cleaned.slice(1);
  }

  // Türkiye için geçerli numara 10 hane ve 5 ile başlamalıdır
  if (cleaned.length !== 10 || !cleaned.startsWith('5')) {
    throw new Error(`Geçersiz telefon numarası formatı: "${s}"`);
  }

  return `+90${cleaned}`;
}
