/**
 * Parses a key-value string separated by semicolons into an object.
 *
 * @param {string} s - The input string formatted like "a=1;b=two;c="
 * @returns {Record<string, string>} The parsed key-value pairs
 */
export function parseKv(s) {
  const result = {};

  if (!s) {
    return result;
  }

  const segments = s.split(';');

  for (const segment of segments) {
    const trimmed = segment.trim();
    if (!trimmed) {
      continue;
    }

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) {
      result[trimmed] = '';
    } else {
      const key = trimmed.slice(0, eqIndex);
      const value = trimmed.slice(eqIndex + 1);
      result[key] = value;
    }
  }

  return result;
}
