```js
/**
 * Calculates the retry delay in milliseconds based on GitHub's Retry-After header.
 *
 * @param {Record<string, string | undefined>} headers
 * @returns {number} Delay in milliseconds, or 0 if header is missing or invalid.
 */
export function githubRetryDelayMs(headers) {
  const retryAfter = headers['retry-after'];
  if (!retryAfter) {
    return 0;
  }

  const seconds = Number(retryAfter);
  if (Number.isFinite(seconds) && seconds > 0) {
    return seconds * 1000;
  }

  const dateMs = Date.parse(retryAfter);
  if (!Number.isNaN(dateMs)) {
    return Math.max(0, dateMs - Date.now());
  }

  return 0;
}
