/**
 * Returns the database connection URL for serverless environments,
 * ensuring the Neon pooled host and required query parameters are configured.
 *
 * @returns {string} The database connection URL.
 */
export function databaseUrl() {
  const urlString = process.env.DATABASE_URL;
  if (!urlString) {
    throw new Error('DATABASE_URL environment variable is not defined');
  }

  const url = new URL(urlString);

  if (!url.hostname.includes('-pooler')) {
    const parts = url.hostname.split('.');
    if (parts.length > 0 && !parts[0].endsWith('-pooler')) {
      parts[0] = `${parts[0]}-pooler`;
      url.hostname = parts.join('.');
    }
  }

  url.searchParams.set('pgbouncer', 'true');
  url.searchParams.set('connection_limit', '1');

  return url.toString();
}
