 * Parses a key-value string separated by semicolons into an object.
 *
 * @param {string} s
 * @returns {Record<string, string>}
 */
export function parseKv(s) {
  const result = {};
  if (!s) return result;

  const pairs = s.split(';');
  for (const pair of pairs) {
    if (!pair) continue;
    const idx = pair.indexOf('=');
    if (idx === -1) {
      result[pair] = '';
    } else {
      const key = pair.slice(0, idx);
      const val = pair.slice(idx + 1);
      result[key] = val;
    }
  }

  return result;
}
