/**
 * Calculates retry delay in milliseconds from GitHub API response headers.
 * GitHub sends the `retry-after` header in seconds.
 *
 * @param {Record<string, string | undefined>} headers - Lowercase header map
 * @returns {number | null} Delay in milliseconds, or null if header is missing/invalid
 */
export function githubRetryDelayMs(headers) {
  const retryAfter = headers?.['retry-after'];
  if (!retryAfter) {
    return null;
  }

  const seconds = Number(retryAfter);
  if (Number.isFinite(seconds) && seconds >= 0) {
    return Math.round(seconds * 1000);
  }

  const dateMs = Date.parse(retryAfter);
  if (!Number.isNaN(dateMs)) {
    return Math.max(0, dateMs - Date.now());
  }

  return null;
}
