```js
/**
 * Calculates the retry delay in milliseconds after a 429 response from the Paraşüt API.
 *
 * Checks standard rate limiting headers:
 * - `retry-after` (seconds or HTTP date)
 * - `x-rate-limit-reset` / `x-ratelimit-reset` (epoch seconds or milliseconds)
 *
 * Defaults to 1000ms if no valid header is found.
 *
 * @param {Record<string, string | number>} headers - Plain headers object (lower-case keys)
 * @returns {number} Milliseconds to wait
 */
export function parasutRetryDelayMs(headers = {}) {
  const retryAfter = headers['retry-after'];
  if (retryAfter !== undefined && retryAfter !== null) {
    const parsedSec = Number(retryAfter);
    if (!Number.isNaN(parsedSec) && parsedSec >= 0) {
      return Math.ceil(parsedSec * 1000);
    }
    const dateParsed = Date.parse(String(retryAfter));
    if (!Number.isNaN(dateParsed)) {
      const diff = dateParsed - Date.now();
      return Math.max(0, diff);
    }
  }

  const resetHeader =
    headers['x-rate-limit-reset'] ??
    headers['x-ratelimit-reset'] ??
    headers['ratelimit-reset'];

  if (resetHeader !== undefined && resetHeader !== null) {
    const resetVal = Number(resetHeader);
    if (!Number.isNaN(resetVal) && resetVal > 0) {
      // If it's in seconds (likely Unix epoch < 1e11), convert to ms
      const resetMs = resetVal < 1e11 ? resetVal * 1000 : resetVal;
      const diff = resetMs - Date.now();
      return Math.max(0, diff);
    }
  }

  return 1000;
}
