/**
 * Normalizes a Turkish phone number into standard international format (+90XXXXXXXXXX).
 * Accepts various input formats such as:
 * - "0532 123 45 67"
 * - "532-123-4567"
 * - "+90 532 123 4567"
 * - "905321234567"
 *
 * @param {string} s - Raw phone number string
 * @returns {string|null} Normalized phone number (+90XXXXXXXXXX) or null if invalid
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') {
    return null;
  }

  // Remove all non-digit characters
  const digits = s.replace(/\D/g, '');

  let nationalNumber = '';

  if (digits.length === 10 && digits.startsWith('5')) {
    // e.g. 5321234567
    nationalNumber = digits;
  } else if (digits.length === 11 && digits.startsWith('05')) {
    // e.g. 05321234567
    nationalNumber = digits.slice(1);
  } else if (digits.length === 12 && digits.startsWith('905')) {
    // e.g. 905321234567
    nationalNumber = digits.slice(2);
  } else if (digits.length === 13 && digits.startsWith('00905')) {
    // e.g. 00905321234567
    nationalNumber = digits.slice(3);
  } else {
    return null;
  }

  return `+90${nationalNumber}`;
}

export default telefonNormalize;
