/**
 * Calculates the retry delay in milliseconds after receiving a 429 response from Paraşüt.
 *
 * @param {Record<string, string | undefined>} headers - Headers object with lowercase keys
 * @returns {number} Delay in milliseconds
 */
export function parasutRetryDelayMs(headers = {}) {
  const retryAfter = headers['retry-after'];
  if (retryAfter !== undefined) {
    const seconds = Number(retryAfter);
    if (!Number.isNaN(seconds)) {
      return Math.max(0, Math.ceil(seconds * 1000));
    }

    const parsedDate = Date.parse(retryAfter);
    if (!Number.isNaN(parsedDate)) {
      return Math.max(0, parsedDate - Date.now());
    }
  }

  const rateLimitReset = headers['x-ratelimit-reset'];
  if (rateLimitReset !== undefined) {
    const resetTime = Number(rateLimitReset);
    if (!Number.isNaN(resetTime)) {
      // If the timestamp is in seconds (standard Unix epoch), convert to ms
      const resetMs = resetTime < 1e12 ? resetTime * 1000 : resetTime;
      return Math.max(0, Math.ceil(resetMs - Date.now()));
    }
  }

  // Default fallback delay if no headers specify a duration
  return 1000;
}
