const RETRYABLE_STATUS_CODES = new Set([408, 429, 500, 502, 503, 504]);
const MAX_ATTEMPTS = 3;

/**
 * Determines whether an outbound HTTP request should be retried.
 *
 * @param {number} status - The HTTP status code received (or 0 for network errors).
 * @param {number} attempt - Number of attempts already made (1 after the first failure).
 * @param {number} [maxAttempts=MAX_ATTEMPTS] - Maximum allowed attempts.
 * @returns {boolean}
 */
export function shouldRetry(status, attempt, maxAttempts = MAX_ATTEMPTS) {
  if (attempt >= maxAttempts) {
    return false;
  }

  // Network failures or connection resets often represented as 0 or undefined
  if (!status || status === 0) {
    return true;
  }

  return RETRYABLE_STATUS_CODES.has(status);
}

export default shouldRetry;
