/**
 * Normalizes a Turkish phone number into a standard format (+905XXXXXXXXX).
 *
 * @param {string} s - Input phone number string in various formats
 * @returns {string} Normalized phone number (+905XXXXXXXXX)
 * @throws {Error} If the phone number is invalid
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Phone number must be a string');
  }

  // Strip all non-digit characters
  let digits = s.replace(/\D/g, '');

  // Handle standard country code and local prefixes
  if (digits.startsWith('90')) {
    digits = digits.slice(2);
  } else if (digits.startsWith('0')) {
    digits = digits.slice(1);
  }

  // Valid Turkish mobile/landline numbers have 10 digits starting with 5 (for mobile)
  // or area codes starting with 2-4, 8, etc.
  if (digits.length !== 10) {
    throw new Error(`Invalid Turkish phone number length: ${s}`);
  }

  return `+90${digits}`;
}
