export function parseKv(s) {
  const result = {};
  if (!s) return result;

  const segments = s.split(';');
  for (const segment of segments) {
    if (!segment) continue;
    const eqIdx = segment.indexOf('=');
    if (eqIdx === -1) {
      result[segment] = '';
    } else {
      const key = segment.slice(0, eqIdx);
      const value = segment.slice(eqIdx + 1);
      result[key] = value;
    }
  }

  return result;
}
