```js
const TIMEZONE = 'Europe/Istanbul';

/**
 * Parses a "YYYY-MM-DD" date string representing a delivery date
 * into a Date instance corresponding to midnight (start of day)
 * in the business timezone.
 *
 * @param {string} s - Date string in "YYYY-MM-DD" format
 * @returns {Date} Date object for that day in the business timezone
 */
export function parseDeliveryDate(s) {
  if (!s || typeof s !== 'string') {
    throw new TypeError('Expected a non-empty date string');
  }

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s.trim());
  if (!match) {
    throw new RangeError(`Invalid date format, expected YYYY-MM-DD: "${s}"`);
  }

  const [, yearStr, monthStr, dayStr] = match;
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);

  // UTC candidate date for midnight
  const utcDate = new Date(Date.UTC(year, month - 1, day, 0, 0, 0));

  // Determine timezone offset for the given date in the target timezone
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: TIMEZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });

  const parts = Object.fromEntries(
    formatter.formatToParts(utcDate).map((p) => [p.type, p.value])
  );

  const asTzUtc = Date.UTC(
    Number(parts.year),
    Number(parts.month) - 1,
    Number(parts.day),
    Number(parts.hour) % 24,
    Number(parts.minute),
    Number(parts.second)
  );

  const offset = asTzUtc - utcDate.getTime();
  return new Date(utcDate.getTime() - offset);
}

export default parseDeliveryDate;
```

