import { AppError } from './errors.js';

export function formatTutar(tutar) {
  let kurus;

  if (typeof tutar === 'bigint') {
    kurus = tutar;
  } else if (typeof tutar === 'number') {
    if (!Number.isSafeInteger(tutar)) {
      throw new AppError('INVALID_AMOUNT', 'Tutar geçerli bir tam sayı olmalıdır.');
    }
    kurus = BigInt(tutar);
  } else if (tutar && typeof tutar === 'object' && typeof tutar.amount === 'bigint') {
    kurus = tutar.amount;
  } else {
    throw new AppError('INVALID_AMOUNT', 'Geçersiz tutar değeri.');
  }

  const isNegative = kurus < 0n;
  const absKurus = isNegative ? -kurus : kurus;

  const lira = absKurus / 100n;
  const rem = absKurus % 100n;

  const liraStr = lira.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const kurusStr = rem.toString().padStart(2, '0');

  const sign = isNegative ? '-' : '';
  return `${sign}${liraStr},${kurusStr} TL`;
}
