```js
/**
 * Rounds a rational value to the nearest integer using half-even (banker's) rounding.
 *
 * @param {bigint} numerator
 * @param {bigint} denominator
 * @returns {bigint}
 */
function roundHalfEven(numerator, denominator) {
  const quotient = numerator / denominator;
  const remainder = numerator % denominator;

  if (remainder === 0n) {
    return quotient;
  }

  const absRemainder = remainder < 0n ? -remainder : remainder;
  const absDenominator = denominator < 0n ? -denominator : denominator;
  const doubleRemainder = absRemainder * 2n;

  if (doubleRemainder < absDenominator) {
    return quotient;
  }

  if (doubleRemainder > absDenominator) {
    return remainder > 0n ? quotient + 1n : quotient - 1n;
  }

  // Exact half tie: round to nearest even integer
  if (quotient % 2n === 0n) {
    return quotient;
  }

  return remainder > 0n ? quotient + 1n : quotient - 1n;
}

/**
 * Computes total VAT (KDV) in kuruş from line net amounts and tax rate percentage.
 * Computes per line in kuruş and rounds each line half-even before summing.
 *
 * @param {Array<number | bigint>} lineNets - Line net amounts in kuruş
 * @param {number | bigint} ratePercent - VAT rate percentage (e.g. 20 for 20%)
 * @returns {number} Total VAT in kuruş
 */
export function invoiceVat(lineNets, ratePercent) {
  const rate = BigInt(ratePercent);
  let totalKdv = 0n;

  for (const net of lineNets) {
    const lineVat = roundHalfEven(BigInt(net) * rate, 100n);
    totalKdv += lineVat;
  }

  return Number(totalKdv);
}
