import { AppError } from './errors.js';

/**
 * Normalizes a Turkish phone number into E.164 format (+905XXXXXXXXX).
 *
 * @param {string} input - Raw phone number string from user input
 * @returns {string} E.164 formatted phone number
 */
export function telefonNormalize(input) {
  if (typeof input !== 'string') {
    throw new AppError('INVALID_PHONE', 'HATA-TELEFON: geçersiz telefon numarası');
  }

  // Strip all non-digit characters except an optional leading plus
  const hasLeadingPlus = input.trim().startsWith('+');
  const digits = input.replace(/\D/g, '');

  let nationalDigits = '';

  if (hasLeadingPlus || digits.startsWith('90')) {
    if (digits.startsWith('90') && digits.length === 12) {
      nationalDigits = digits.slice(2);
    }
  } else if (digits.startsWith('0') && digits.length === 11) {
    nationalDigits = digits.slice(1);
  } else if (digits.length === 10) {
    nationalDigits = digits;
  }

  // Valid Turkish mobile/landline national number: 10 digits starting with 5 (or valid area code)
  if (!nationalDigits || nationalDigits.length !== 10 || !nationalDigits.startsWith('5')) {
    throw new AppError('INVALID_PHONE', 'HATA-TELEFON: geçersiz telefon numarası');
  }

  return `+90${nationalDigits}`;
}
