/**
 * Serializes an order object to a JSON string for webhook payloads,
 * converting BigInt kuruş amounts in Money objects into decimal strings.
 *
 * @param {object} order
 * @returns {string}
 */
export function orderToJson(order) {
  return JSON.stringify(order, (key, value) => {
    if (typeof value === 'bigint') {
      const kurus = value;
      const negative = kurus < 0n;
      const absKurus = negative ? -kurus : kurus;
      const whole = absKurus / 100n;
      const fraction = (absKurus % 100n).toString().padStart(2, '0');
      const formatted = `${whole.toString()}.${fraction}`;
      return negative ? `-${formatted}` : formatted;
    }
    return value;
  });
}
