/**
 * Kuruş cinsinden integer tutarı standart gösterim formatına çevirir.
 * Örnek: 123450 -> "1.234,50 TL"
 *
 * @param {number|bigint} tutar - Kuruş cinsinden tutar
 * @returns {string} Formatlanmış tutar metni
 */
export function formatTutar(tutar) {
  const kurusBigInt = typeof tutar === 'bigint' ? tutar : BigInt(Math.round(Number(tutar) || 0));
  const isNegative = kurusBigInt < 0n;
  const absKurus = isNegative ? -kurusBigInt : kurusBigInt;

  const lira = absKurus / 100n;
  const kurus = absKurus % 100n;

  const liraStr = lira.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const kurusStr = kurus.toString().padStart(2, '0');

  return `${isNegative ? '-' : ''}${liraStr},${kurusStr} TL`;
}
