/**
 * Returns the database connection URL configured with Neon pooling parameters.
 *
 * @param {string} [baseUrl=process.env.DATABASE_URL] - Base connection string
 * @returns {string} Configured database connection URL
 */
export function databaseUrl(baseUrl = process.env.DATABASE_URL) {
  if (!baseUrl) {
    throw new Error('DATABASE_URL is not set');
  }

  const url = new URL(baseUrl);

  if (!url.hostname.includes('-pooler')) {
    const parts = url.hostname.split('.');
    parts[0] = `${parts[0]}-pooler`;
    url.hostname = parts.join('.');
  }

  url.searchParams.set('pgbouncer', 'true');
  url.searchParams.set('connection_limit', '1');

  return url.toString();
}
