/**
 * Normalizes a Turkish phone number into standard international format (+90XXXXXXXXXX).
 * Accepts formats like "0532 123 45 67", "532-123-4567", "+90 532 123 45 67", "00905321234567".
 *
 * @param {string} s - Input phone number string
 * @returns {string} Normalized phone number in +90XXXXXXXXXX format
 * @throws {Error} If the phone number is invalid
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Telefon numarası geçerli bir metin olmalıdır.');
  }

  // Sadece rakamları ayıkla
  let digits = s.replace(/\D/g, '');

  // Başındaki uluslararası çıkış kodlarını (0090) veya ülke kodunu (90) temizle
  if (digits.startsWith('0090')) {
    digits = digits.slice(4);
  } else if (digits.startsWith('90') && digits.length === 12) {
    digits = digits.slice(2);
  }

  // Başında 0 varsa kaldır (ör. 0532 -> 532)
  if (digits.startsWith('0')) {
    digits = digits.slice(1);
  }

  // Türkiye için 10 haneli geçerli bir mobil/sabit numara olmalı (5XX XXX XX XX)
  if (digits.length !== 10 || !digits.startsWith('5')) {
    throw new Error(`Geçersiz telefon numarası: "${s}"`);
  }

  return `+90${digits}`;
}
