/**
 * Calculates the retry delay in milliseconds from GitHub API response headers.
 * GitHub sends the `retry-after` header value in seconds.
 *
 * @param {Record<string, string | undefined>} headers - Headers object with lower-case keys.
 * @returns {number | null} Delay in milliseconds, or null if header is missing or invalid.
 */
export function githubRetryDelayMs(headers) {
  const retryAfter = headers?.['retry-after'];

  if (retryAfter === undefined || retryAfter === null || retryAfter === '') {
    return null;
  }

  const seconds = Number(retryAfter);

  if (Number.isNaN(seconds) || seconds < 0) {
    return null;
  }

  return Math.round(seconds * 1000);
}
