/**
 * Normalizes a Turkish phone number into E.164 format (+90XXXXXXXXXX).
 * 
 * @param {string} s - Input phone string (e.g. "0532 123 45 67", "532-123-4567")
 * @returns {string} Normalized phone number in E.164 format
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') {
    throw new Error('HATA-TEL: geçersiz telefon numarası');
  }

  const digits = s.replace(/\D/g, '');

  if (digits.length === 10 && digits.startsWith('5')) {
    return `+90${digits}`;
  }

  if (digits.length === 11 && digits.startsWith('05')) {
    return `+90${digits.slice(1)}`;
  }

  if (digits.length === 12 && digits.startsWith('905')) {
    return `+${digits}`;
  }

  throw new Error('HATA-TEL: geçersiz telefon numarası');
}
