/**
 * Formats an integer number of US cents as a USD currency string ($1,234.50).
 *
 * @param {number} cents
 * @returns {string}
 */
export function formatUsd(cents) {
  const isNegative = cents < 0;
  const absCents = Math.abs(Math.trunc(cents));
  const dollars = Math.floor(absCents / 100);
  const remainder = absCents % 100;

  const dollarsFormatted = dollars.toLocaleString('en-US');
  const centsFormatted = remainder.toString().padStart(2, '0');

  const formatted = `$${dollarsFormatted}.${centsFormatted}`;
  return isNegative ? `-${formatted}` : formatted;
}
