/**
 * Validates a Turkish Republic Identity Number (TCKN).
 *
 * @param {string} s
 * @returns {true}
 * @throws {Error}
 */
export function validateTckn(s) {
  const str = String(s);

  if (!/^\d{11}$/.test(str)) {
    throw new Error('HATA-TCKN: Kimlik numarası 11 haneli olmalıdır');
  }

  if (str.startsWith('0')) {
    throw new Error('HATA-TCKN: Kimlik numarası 0 ile başlayamaz');
  }

  const digits = str.split('').map(Number);

  const oddSum = digits[0] + digits[2] + digits[4] + digits[6] + digits[8];
  const evenSum = digits[1] + digits[3] + digits[5] + digits[7];
  const digit10 = ((oddSum * 7) - evenSum) % 10;
  const normalizedDigit10 = digit10 < 0 ? digit10 + 10 : digit10;

  if (normalizedDigit10 !== digits[9]) {
    throw new Error('HATA-TCKN: Geçersiz kimlik numarası');
  }

  const sumFirst10 = digits.slice(0, 10).reduce((acc, d) => acc + d, 0);
  if (sumFirst10 % 10 !== digits[10]) {
    throw new Error('HATA-TCKN: Geçersiz kimlik numarası');
  }

  return true;
}
