/**
 * Normalizes a Turkish phone number into E.164 format (+905XXXXXXXXX).
 *
 * @param {string} s - Input phone string.
 * @returns {string} E.164 formatted phone number.
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') {
    throw new TypeError('HATA-TEL: telefon numarası metin olmalıdır');
  }

  const digits = s.replace(/\D/g, '');

  let nationalNumber = digits;
  if (digits.startsWith('90') && digits.length === 12) {
    nationalNumber = digits.slice(2);
  } else if (digits.startsWith('0') && digits.length === 11) {
    nationalNumber = digits.slice(1);
  }

  if (nationalNumber.length !== 10 || !nationalNumber.startsWith('5')) {
    throw new Error('HATA-TEL: geçersiz telefon numarası');
  }

  return `+90${nationalNumber}`;
}
