/**
 * Parses a key-value string separated by semicolons.
 *
 * @param {string} s - Input string like "a=1;b=two;c="
 * @returns {Record<string, string>}
 */
export function parseKv(s) {
  const result = {};
  if (!s) return result;

  for (const segment of s.split(";")) {
    if (!segment) continue;

    const idx = segment.indexOf("=");
    if (idx === -1) {
      result[segment] = "";
    } else {
      const key = segment.slice(0, idx);
      const val = segment.slice(idx + 1);
      result[key] = val;
    }
  }

  return result;
}
