```js
/**
 * Calculates the retry delay in milliseconds after a 429 response from the Paraşüt API.
 *
 * Note: Paraşüt sends `retry-after` in MILLISECONDS, not seconds.
 *
 * @param {Record<string, string | string[] | undefined>} headers
 * @returns {number} Delay in milliseconds (minimum 0)
 */
export function parasutRetryDelayMs(headers) {
  const DEFAULT_DELAY_MS = 60_000;

  if (!headers || typeof headers !== 'object') {
    return DEFAULT_DELAY_MS;
  }

  const getHeader = (name) => {
    const val = headers[name.toLowerCase()];
    return Array.isArray(val) ? val[0] : val;
  };

  const retryAfter = getHeader('retry-after');
  if (retryAfter != null) {
    const ms = Number(retryAfter);
    if (!Number.isNaN(ms)) {
      return Math.max(0, Math.ceil(ms));
    }

    const dateMs = Date.parse(retryAfter);
    if (!Number.isNaN(dateMs)) {
      return Math.max(0, dateMs - Date.now());
    }
  }

  const resetHeader = getHeader('x-rate-limit-reset') ?? getHeader('x-ratelimit-reset');
  if (resetHeader != null) {
    const resetVal = Number(resetHeader);
    if (!Number.isNaN(resetVal)) {
      if (resetVal > 946684800000) {
        return Math.max(0, resetVal - Date.now());
      }
      if (resetVal > 946684800) {
        return Math.max(0, resetVal * 1000 - Date.now());
      }
      return Math.max(0, Math.ceil(resetVal));
    }
  }

  return DEFAULT_DELAY_MS;
}
