/**
 * Calculates the retry delay in milliseconds after a 429 response from the Paraşüt API.
 *
 * Paraşüt (Ruby on Rails / Rack::Attack) sends `Retry-After` already formatted in
 * milliseconds (or seconds depending on version), but values >= 1000 typically
 * represent milliseconds. Caps the delay to avoid exceeding worker timeouts.
 *
 * @param {Record<string, string | string[] | undefined>} headers
 * @returns {number} Delay in milliseconds (capped between 0 and MAX_DELAY_MS)
 */
export function parasutRetryDelayMs(headers) {
  const DEFAULT_DELAY_MS = 60_000;
  const MAX_DELAY_MS = 120_000;

  if (!headers || typeof headers !== 'object') {
    return DEFAULT_DELAY_MS;
  }

  const getHeader = (name) => {
    const val = headers[name.toLowerCase()];
    return Array.isArray(val) ? val[0] : val;
  };

  const retryAfter = getHeader('retry-after');
  if (retryAfter != null) {
    const parsedNum = Number(retryAfter);
    if (!Number.isNaN(parsedNum)) {
      // Paraşüt sends Retry-After as an integer representing milliseconds (e.g. 1500 -> 1.5s).
      // If it's small (<= 120), treat as seconds; otherwise it's already milliseconds.
      const delayMs = parsedNum <= 120 ? parsedNum * 1000 : parsedNum;
      return Math.min(Math.max(0, Math.ceil(delayMs)), MAX_DELAY_MS);
    }

    const dateMs = Date.parse(retryAfter);
    if (!Number.isNaN(dateMs)) {
      return Math.min(Math.max(0, dateMs - Date.now()), MAX_DELAY_MS);
    }
  }

  const resetHeader = getHeader('x-rate-limit-reset') ?? getHeader('x-ratelimit-reset');
  if (resetHeader != null) {
    const resetVal = Number(resetHeader);
    if (!Number.isNaN(resetVal)) {
      if (resetVal > 946684800) {
        return Math.min(Math.max(0, resetVal * 1000 - Date.now()), MAX_DELAY_MS);
      }
      const delayMs = resetVal <= 120 ? resetVal * 1000 : resetVal;
      return Math.min(Math.max(0, Math.ceil(delayMs)), MAX_DELAY_MS);
    }
  }

  return DEFAULT_DELAY_MS;
}
