import * as timezoneModule from './timezone.js';

const TIMEZONE =
  timezoneModule.BUSINESS_TIMEZONE ??
  timezoneModule.TIMEZONE ??
  timezoneModule.businessTimezone ??
  timezoneModule.default ??
  timezoneModule.timezone;

/**
 * Returns the UTC offset in minutes for a given instant and timezone.
 * offset = local - UTC
 */
function getTimezoneOffset(date, timeZone) {
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone,
    timeZoneName: 'shortOffset',
    hourCycle: 'h23',
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: 'numeric',
    second: 'numeric',
  });

  const parts = formatter.formatToParts(date);
  const timeZoneNamePart = parts.find((p) => p.type === 'timeZoneName');
  if (!timeZoneNamePart) {
    throw new Error(`Unable to determine timezone offset for ${timeZone}`);
  }

  // Format can be "GMT", "GMT+X", "GMT-X", "GMT+XX:XX", etc.
  const str = timeZoneNamePart.value.replace(/^GMT|^UTC/, '');
  if (!str) return 0;

  const match = str.match(/^([+-])(\d{1,2})(?::?(\d{2}))?$/);
  if (!match) return 0;

  const sign = match[1] === '-' ? -1 : 1;
  const hours = parseInt(match[2], 10);
  const minutes = match[3] ? parseInt(match[3], 10) : 0;
  return sign * (hours * 60 + minutes);
}

/**
 * Given a date-only string like "2026-03-01", returns a Date
 * representing midnight at the start of that day in the business timezone.
 *
 * @param {string} s
 * @returns {Date}
 */
export function parseDeliveryDate(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Expected a date string');
  }

  const match = s.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) {
    throw new Error(`Invalid date format: "${s}". Expected YYYY-MM-DD.`);
  }

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10) - 1;
  const day = parseInt(match[3], 10);

  // Guess UTC midnight for that calendar date
  let utcMs = Date.UTC(year, month, day, 0, 0, 0, 0);

  // Adjust for the target timezone offset
  const tz = typeof TIMEZONE === 'function' ? TIMEZONE() : TIMEZONE;
  const offsetMinutes = getTimezoneOffset(new Date(utcMs), tz);
  utcMs -= offsetMinutes * 60 * 1000;

  // Re-verify in case offset changed across daylight saving boundary
  const refinedOffset = getTimezoneOffset(new Date(utcMs), tz);
  if (refinedOffset !== offsetMinutes) {
    utcMs = Date.UTC(year, month, day, 0, 0, 0, 0) - refinedOffset * 60 * 1000;
  }

  return new Date(utcMs);
}
