export function formatTutar(tutar) {
  if (tutar == null || isNaN(tutar)) return '';
  const num = Number(tutar);
  const negative = num < 0;
  const absNum = Math.abs(num);
  const [intPart, decPart = '00'] = absNum.toFixed(2).split('.');
  const reversed = intPart.split('').reverse().join('');
  const withDots = reversed.replace(/\d{3}(?=\d)/g, '$&.');
  const formattedInt = withDots.split('').reverse().join('');
  return (negative ? '-' : '') + formattedInt + ',' + decPart;
}
