export default function parseKv(s) {
  const result = {};
  if (!s) return result;
  const segments = s.split(';');
  for (const seg of segments) {
    if (seg === '') continue;
    const eqIndex = seg.indexOf('=');
    if (eqIndex === -1) continue;
    const key = seg.slice(0, eqIndex);
    if (key === '') continue;
    const value = seg.slice(eqIndex + 1);
    result[key] = value;
  }
  return result;
}
