```js
import { BUSINESS_TIMEZONE } from './config.js';

/**
 * Parses a date-only string like "2026-03-01" and returns a Date object
 * representing midnight of that day in the business timezone.
 *
 * @param {string} s - Date string in YYYY-MM-DD format.
 * @returns {Date} Date for the given day at 00:00 in the business timezone.
 */
export function parseDeliveryDate(s) {
  const [year, month, day] = s.split('-').map(Number);
  const utcMidnight = new Date(Date.UTC(year, month - 1, day));

  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: BUSINESS_TIMEZONE,
    timeZoneName: 'longOffset',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });

  const parts = formatter.formatToParts(utcMidnight);
  const tzPart = parts.find(p => p.type === 'timeZoneName');
  if (!tzPart) {
    // Fallback: return UTC midnight (should not happen with a valid timezone)
    return utcMidnight;
  }

  const match = tzPart.value.match(/GMT([+-])(\d{1,2}):?(\d{2})?/);
  if (!match) {
    return utcMidnight;
  }

  const sign = match[1] === '+' ? 1 : -1;
  const hours = parseInt(match[2], 10);
  const minutes = parseInt(match[3] || '0', 10);
  const offsetMs = sign * (hours * 60 + minutes) * 60 * 1000;

  // Subtract the offset so that the resulting Date's local time in the
  // business timezone is midnight of the requested day.
  return new Date(utcMidnight.getTime() - offsetMs);
}
