import { toAscii } from './text.js';

/**
 * Converts a string to a URL-friendly slug.
 * - Lowercases the string
 * - Replaces spaces and punctuation with single dashes
 * - Trims leading/trailing dashes
 * - Reuses toAscii to normalize accented characters
 *
 * @param {string} s - The input string
 * @returns {string} The slug
 */
export function slugify(s) {
  const ascii = toAscii(s);
  const lower = ascii.toLowerCase();
  const dashed = lower.replace(/[^a-z0-9-]/g, '-');
  const collapsed = dashed.replace(/-+/g, '-');
  return collapsed.replace(/^-+|-+$/g, '');
}
