/**
 * Fetches all invoices by paginating through the billing API.
 *
 * @param {(cursor: string|null) => Promise<{items: Array, next_cursor: string}>} getPage
 *   Function that calls the billing API with the given cursor and returns a page.
 *   The first call should use `null` as cursor.
 * @returns {Promise<Array>} All items from all pages.
 */
export async function fetchAllInvoices(getPage) {
  let cursor = null;
  const allItems = [];

  while (true) {
    const { items, next_cursor } = await getPage(cursor);
    allItems.push(...items);
    if (!next_cursor) break;
    cursor = next_cursor;
  }

  return allItems;
}
