import { AppError } from './errors.js';

/**
 * Parses a port string and returns the port number.
 * Throws an AppError if the value is not an integer between 1 and 65535.
 *
 * @param {string} s - The port string to parse.
 * @returns {number} The port number.
 * @throws {AppError} With code INVALID_PORT if validation fails.
 */
export function parsePort(s) {
  const trimmed = (s ?? '').trim();
  if (trimmed === '') {
    throw new AppError('INVALID_PORT', 'HATA-INVALID_PORT: geçersiz port numarası');
  }

  const num = Number(trimmed);
  if (!Number.isInteger(num) || !Number.isFinite(num)) {
    throw new AppError('INVALID_PORT', 'HATA-INVALID_PORT: geçersiz port numarası');
  }

  if (num < 1 || num > 65535) {
    throw new AppError('INVALID_PORT', 'HATA-INVALID_PORT: geçersiz port numarası');
  }

  return num;
}
