```js
/**
 * Normalizes a user-supplied phone number to E.164 format (+90XXXXXXXXXX).
 * Strips all non‑digit characters (except a leading '+') and ensures the
 * result starts with +90.
 *
 * @param {string} s - Raw phone input (e.g. "0532 123 45 67" or "+90 532 123 45 67")
 * @returns {string} Normalized number, e.g. "+905321234567"
 */
export function telefonNormalize(s) {
  // Keep only digits and an optional leading '+'
  const cleaned = s.replace(/[^\d+]/g, '');

  // Already in canonical form
  if (/^\+90\d{10}$/.test(cleaned)) return cleaned;

  // Replace a leading "90" with "+90"
  if (/^90\d{10}$/.test(cleaned)) return '+' + cleaned;

  // Replace a leading "0" with "+90"
  if (/^0\d{10}$/.test(cleaned)) return '+90' + cleaned.slice(1);

  // Assume a bare 10‑digit Turkish number (no prefix)
  if (/^\d{10}$/.test(cleaned)) return '+90' + cleaned;

  // Fallback: just prepend +90 (covers short codes etc.)
  return '+90' + cleaned.replace(/^0+/, '');
}
