```js
/**
 * Compute total KDV (VAT) for a list of line net amounts (in kuruş) at a given rate.
 * Each line's VAT is rounded half-even (banker's rounding) before summing.
 *
 * @param {number[]} lineNets - Array of integer kuruş amounts (positive).
 * @param {number} ratePercent - VAT rate as a percentage (e.g., 20 for 20%).
 * @returns {number} Total KDV in kuruş (integer).
 */
export function invoiceVat(lineNets, ratePercent) {
  let total = 0;
  for (const net of lineNets) {
    const exact = net * ratePercent / 100;
    const floor = Math.floor(exact);
    const diff = exact - floor;
    let rounded;
    if (diff < 0.5) {
      rounded = floor;
    } else if (diff > 0.5) {
      rounded = Math.ceil(exact);
    } else {
      // exactly 0.5 → round to nearest even
      rounded = floor % 2 === 0 ? floor : floor + 1;
    }
    total += rounded;
  }
  return total;
}
