import Database from 'better-sqlite3';

/**
 * Opens a SQLite database with WAL mode and a busy timeout to prevent
 * SQLITE_BUSY errors in concurrent test scenarios.
 *
 * @param {string} path  Path to the SQLite database file.
 * @param {typeof Database} Database  The better-sqlite3 Database constructor.
 * @returns {import('better-sqlite3').Database}
 */
export function openDb(path, Database) {
  const db = new Database(path);

  // Enable WAL mode for better concurrent read/write performance.
  db.pragma('journal_mode = WAL');

  // Set a busy timeout (in milliseconds) so that concurrent writes wait
  // instead of immediately failing with SQLITE_BUSY.
  db.pragma('busy_timeout = 5000');

  return db;
}
