```js
/**
 * Parses a date-only string (YYYY-MM-DD) into a Date object representing
 * midnight in the business timezone (America/New_York).
 *
 * @param {string} s - Date string in "YYYY-MM-DD" format.
 * @returns {Date} Date object for that day at 00:00:00 in America/New_York.
 */
export function parseDeliveryDate(s) {
  const tz = 'America/New_York';
  const [year, month, day] = s.split('-').map(Number);
  // Create a UTC midnight date to query the timezone offset
  const utcMidnight = new Date(Date.UTC(year, month - 1, day));

  // Get the timezone offset string (e.g., "GMT-05:00" or "GMT-04:00")
  const formatter = new Intl.DateTimeFormat('en', {
    timeZone: tz,
    timeZoneName: 'longOffset',
  });
  const parts = formatter.formatToParts(utcMidnight);
  const tzPart = parts.find(p => p.type === 'timeZoneName');
  if (!tzPart) throw new Error('Could not determine timezone offset');

  const offsetStr = tzPart.value; // e.g., "GMT-05:00"
  const match = offsetStr.match(/GMT([+-])(\d{2}):(\d{2})/);
  if (!match) throw new Error('Unexpected offset format');
  const sign = match[1] === '+' ? 1 : -1;
  const hours = parseInt(match[2], 10);
  const minutes = parseInt(match[3], 10);
  const totalOffsetMinutes = sign * (hours * 60 + minutes);

  // Build ISO 8601 string with the correct offset
  const offsetSign = totalOffsetMinutes >= 0 ? '+' : '-';
  const absOffset = Math.abs(totalOffsetMinutes);
  const offsetHours = Math.floor(absOffset / 60);
  const offsetMins = absOffset % 60;
  const offsetFormatted = `${offsetSign}${String(offsetHours).padStart(2, '0')}:${String(offsetMins).padStart(2, '0')}`;
  const isoString = `${s}T00:00:00${offsetFormatted}`;

  return new Date(isoString);
}
