/**
 * Returns the delay in milliseconds from a GitHub API retry-after header.
 * GitHub sends the value in seconds. If the header is missing or invalid, returns 0.
 *
 * @param {Record<string, string | string[] | undefined>} headers - Plain object with lower-case keys.
 * @returns {number} Delay in milliseconds.
 */
export function githubRetryDelayMs(headers) {
  const value = headers?.['retry-after'];
  if (value === undefined || value === null) return 0;

  // Header may be a string or an array (take first element)
  const raw = Array.isArray(value) ? value[0] : value;
  const seconds = parseInt(String(raw), 10);
  if (Number.isNaN(seconds) || seconds < 0) return 0;

  return seconds * 1000;
}
```

