/**
 * Splits an array into chunks of the given size.
 * The last chunk may be shorter than `n`.
 *
 * @param {Array} dizi - The array to split.
 * @param {number} n - The chunk size (positive integer).
 * @returns {Array<Array>} An array of chunks.
 */
export function parcala(dizi, n) {
  if (!Array.isArray(dizi) || n < 1) return [];
  const result = [];
  for (let i = 0; i < dizi.length; i += n) {
    result.push(dizi.slice(i, i + n));
  }
  return result;
}
