export function formatTutar(tutar) {
  if (typeof tutar === 'bigint') {
    const neg = tutar < 0n ? '-' : '';
    const abs = tutar < 0n ? -tutar : tutar;
    const tl = abs / 100n;
    const kr = abs % 100n;
    const tlStr = tl.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    const krStr = kr.toString().padStart(2, '0');
    return `${neg}${tlStr},${krStr} TL`;
  } else {
    const neg = tutar < 0 ? '-' : '';
    const abs = Math.abs(tutar);
    const tl = Math.floor(abs / 100);
    const kr = abs % 100;
    const tlStr = tl.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    const krStr = kr.toString().padStart(2, '0');
    return `${neg}${tlStr},${krStr} TL`;
  }
}
