```js
/**
 * Computes total KDV (VAT) in kuruş using per‑line banker's rounding.
 *
 * @param {number[]} lineNets - Array of net amounts in kuruş (integers).
 * @param {number} ratePercent - VAT rate as a percentage (e.g. 20 for 20%).
 * @returns {number} Total KDV in kuruş.
 */
export default function invoiceVat(lineNets, ratePercent) {
  function bankersRound(value) {
    const floored = Math.floor(value);
    const diff = value - floored;
    if (diff < 0.5) return floored;
    if (diff > 0.5) return Math.ceil(value);
    // Exactly 0.5 – round to nearest even integer
    return floored % 2 === 0 ? floored : floored + 1;
  }

  let total = 0;
  for (const net of lineNets) {
    const vat = (net * ratePercent) / 100;
    total += bankersRound(vat);
  }
  return total;
}
```

