export default function validateTckn(s) {
  const str = String(s);
  if (!/^\d{11}$/.test(str) || str[0] === '0') {
    throw new Error('TC Kimlik Numarası 11 haneli olmalı ve 0 ile başlamamalıdır.');
  }

  const d = str.split('').map(Number);

  // 10th digit check (based on first 9 digits)
  const oddSum = d[0] + d[2] + d[4] + d[6] + d[8];
  const evenSum = d[1] + d[3] + d[5] + d[7];
  const d10Calc = (oddSum * 7 - evenSum) % 10;
  if (d10Calc !== d[9]) {
    throw new Error('TC Kimlik Numarası geçersiz.');
  }

  // 11th digit check (sum of first 10 digits mod 10)
  const sum10 = d.slice(0, 10).reduce((a, b) => a + b, 0);
  const d11Calc = sum10 % 10;
  if (d11Calc !== d[10]) {
    throw new Error('TC Kimlik Numarası geçersiz.');
  }

  return true;
}
```

