/**
 * Sums a list of money values (all the same currency).
 * @param {Array<{amount: bigint, currency: string}>} values
 * @returns {{amount: bigint, currency: string}}
 */
export function sumMoney(values) {
  if (values.length === 0) {
    throw new Error('sumMoney: values must not be empty');
  }

  const currency = values[0].currency;
  let total = 0n;

  for (const m of values) {
    if (m.currency !== currency) {
