import { AppError } from './errors.js';

/**
 * Parse a port string into an integer between 1 and 65535.
 * Throws an AppError with code INVALID_PORT if the input is not valid.
 */
export function parsePort(s) {
  const trimmed = String(s).trim();
  if (trimmed === '') {
    throw new AppError('INVALID_PORT', 'Port cannot be empty');
  }
  const num = Number(trimmed);
  if (!Number.isFinite(num) || !Number.isInteger(num)) {
    throw new AppError('INVALID_PORT', `Port must be an integer, got "${trimmed}"`);
  }
  if (num < 1 || num > 65535) {
    throw new AppError('INVALID_PORT', `Port must be between 1 and 65535, got ${num}`);
  }
  return num;
}
