  const evenSum = first9.reduce((sum, d, i) => (i % 2 === 1 ? sum + d : sum), 0);

  const d10 = ((oddSum * 7 - evenSum) % 10 + 10) % 10;
  const d11 = (digits.slice(0, 10).reduce((a, b) => a + b, 0)) % 10;

  if (digits[9] !== d10 || digits[10] !== d11) {
    throw new Error('TCKN doğrulama kurallarına uymuyor');
