export function parasutRetryDelayMs(headers) {
  const now = Date.now();

  const retryAfter = headers?.['retry-after'];
  if (retryAfter != null) {
    const trimmed = String(retryAfter).trim();
    const seconds = Number(trimmed);
    if (Number.isFinite(seconds) && trimmed !== '') {
      return Math.max(0, seconds * 1000);
    }

    const dateMs = Date.parse(retryAfter);
    if (!Number.isNaN(dateMs)) {
      return Math.max(0, dateMs - now);
    }
  }

  const reset = headers?.['x-ratelimit-reset'];
  if (reset != null) {
    const trimmed = String(reset).trim();
    const value = Number(trimmed);
    if (Number.isFinite(value) && trimmed !== '') {
      const resetMs = value > 1e11 ? value : value * 1000;
      return Math.max(0, resetMs - now);
    }

    const dateMs = Date.parse(reset);
    if (!Number.isNaN(dateMs)) {
      return Math.max(0, dateMs - now);
    }
  }

  return 0;
}
