export function telefonNormalize(s) {
  // Temizle: sadece rakamlar ve baştaki '+' kalır
  let cleaned = s.trim().replace(/[^0-9+]/g, '');
  // Eğer '+' varsa kaldır ve sonra tekrar ekleyeceğiz
  let hasPlus = cleaned.startsWith('+');
  if (hasPlus) cleaned = cleaned.slice(1);

  // Şimdi sadece rakamlar var
  // Uzunluk ve başlangıca göre normalize et
  if (cleaned.startsWith('00')) {
    // 00 ile başlayan uluslararası
    cleaned = cleaned.slice(2);
  } else if (cleaned.startsWith('0') && cleaned.length === 11) {
    // 0 ile başlayan 11 haneli (şehir içi)
    cleaned = cleaned.slice(1);
  }
  // Eğer 10 haneli ve 0 ile başlamıyorsa (zaten ulusal numara)
  // veya 90 ile başlayıp 12 haneliyse (ülke kodu var)
  // sonra +90 ekle

  // Eğer cleaned 90 ile başlıyorsa ve 12 haneliyse ülke kodu zaten var
  if (cleaned.startsWith('90') && cleaned.length === 12) {
    // ülke kodu var, sadece başına '+' ekle
    return '+' + cleaned;
  }

  // Diğer durumlarda 10 haneli ulusal numara olduğunu varsay
  if (cleaned.length === 10) {
    return '+90' + cleaned;
  }

  // Hiçbir kurala uymazsa olduğu gibi döndür (hatalı giriş olabilir)
  // Yine de başına '+' eklemeyi dene
  return (hasPlus ? '+' : '') + cleaned;
}
```

