import { AppError } from './errors.js';

export function validateTckn(s) {
  const value = typeof s === 'string' ? s.trim() : String(s ?? '');

  if (!/^[1-9]\d{10}$/.test(value)) {
    throw new AppError(
      'INVALID_TCKN',
      'HATA-INVALID_TCKN: TC kimlik numarası 11 haneli olmalı ve 0 ile başlamamalıdır.'
    );
  }

  const digits = value.split('').map(Number);

  const oddSum = digits[0] + digits[2] + digits[4] + digits[6] + digits[8];
  const evenSum = digits[1] + digits[3] + digits[5] + digits[7];

  const tenthDigit = ((oddSum * 7 - evenSum) % 10 + 10) % 10;
  const eleventhDigit = digits.slice(0, 10).reduce((a, b) => a + b, 0) % 10;

  if (digits[9] !== tenthDigit || digits[10] !== eleventhDigit) {
    throw new AppError('INVALID_TCKN', 'HATA-INVALID_TCKN: geçersiz kimlik numarası');
  }

  return true;
}
