const BUSINESS_TIMEZONE = 'America/New_York';

function getTimezoneOffset(date, timeZone) {
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone,
    timeZoneName: 'longOffset',
  });
  const parts = formatter.formatToParts(date);
  const tzPart = parts.find(p => p.type === 'timeZoneName').value;
  const sign = tzPart[3] === '-' ? -1 : 1;
  const [hours, minutes] = tzPart.slice(4).split(':').map(Number);
  return sign * (hours * 60 + minutes);
}

export function parseDeliveryDate(s) {
  const [year, month, day] = s.split('-').map(Number);
  let utcMidnight = new Date(Date.UTC(year, month - 1, day));
  let offset = getTimezoneOffset(utcMidnight, BUSINESS_TIMEZONE);
  let localMidnight = new Date(utcMidnight.getTime() - offset * 60000);
  offset = getTimezoneOffset(localMidnight, BUSINESS_TIMEZONE);
  localMidnight = new Date(utcMidnight.getTime() - offset * 60000);
  return localMidnight;
}
```

