export function invoiceVat(lineNets, ratePercent) {
  const rate = BigInt(ratePercent);
  let total = 0n;

  for (const net of lineNets) {
    const numerator = BigInt(net) * rate;
    let quotient = numerator / 100n;
    const remainder = numerator % 100n;

    if (remainder > 50n) {
      quotient += 1n;
    } else if (remainder === 50n && quotient % 2n !== 0n) {
      quotient += 1n;
    }

    total += quotient;
  }

  return Number(total);
}
