```js
/**
 * Compute total KDV (VAT) for invoice lines using banker's rounding (half-even).
 * @param {number[]} lineNets - Array of net amounts in kuruş (integers).
 * @param {number} ratePercent - VAT rate as a percentage (e.g., 18 for 18%).
 * @returns {number} Total KDV in kuruş.
 */
export default function invoiceVat(lineNets, ratePercent) {
  const factor = ratePercent / 100;
  let total = 0;
  for (const net of lineNets) {
    total += bankersRound(net * factor);
  }
  return total;
}

/**
 * Round a number to the nearest integer, with ties (0.5) going to the nearest even integer.
 * @param {number} x
 * @returns {number}
 */
function bankersRound(x) {
  const r = Math.round(x);
  const diff = x - r;
  // If exactly 0.5 (or -0.5) and the rounded value is odd, adjust toward the even integer
  if (Math.abs(diff) === 0.5 && r % 2 !== 0) {
    return r - (x > 0 ? 1 : -1);
  }
  return r;
}
