import { AppError } from './errors.js';

/**
 * Normalizes a user-provided phone number to E.164 format (+90XXXXXXXXXX).
 * Strips all non-digit characters, handles leading 0, 90, +90, or bare numbers.
 * Validates that the result has exactly 10 digits after the +90 country code.
 * @param {string} s - Raw phone input (e.g. "0532 123 45 67", "532-123-4567", "+905321234567")
 * @returns {string} Normalized phone in E.164 format (e.g. "+905321234567")
 * @throws {AppError} If the input cannot be normalized to a valid Turkish phone number.
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string' || s.trim().length === 0) {
    throw new AppError('INVALID_PHONE', 'HATA-INVALID_PHONE: geçersiz telefon numarası');
  }

  // Remove all characters except digits and a leading '+'
  let cleaned = s.replace(/[^\d+]/g, '');

  // Normalize leading characters
  if (cleaned.startsWith('+')) {
    // Already has +, keep as is
  } else if (cleaned.startsWith('00')) {
    // International prefix 00 → replace with +
    cleaned = '+' + cleaned.slice(2);
  } else if (cleaned.startsWith('90')) {
    // Starts with 90 (no +) → prepend +
    cleaned = '+' + cleaned;
  } else if (cleaned.startsWith('0')) {
    // Local number starting with 0 → drop 0 and prepend +90
    cleaned = '+90' + cleaned.slice(1);
  } else {
    // Assume it's a local number without leading 0 → prepend +90
    cleaned = '+90' + cleaned;
  }

  // Validate structure: must start with +90 followed by exactly 10 digits
  const e164Regex = /^\+90\d{10}$/;
  if (!e164Regex.test(cleaned)) {
    throw new AppError('INVALID_PHONE', 'HATA-INVALID_PHONE: geçersiz telefon numarası');
  }

  return cleaned;
}
