  const str = String(s).trim();

  if (!/^\d{11}$/.test(str)) {
    throw new Error('TC Kimlik No 11 haneli olmalıdır');
  }

  if (str[0] === '0') {
    throw new Error('TC Kimlik No 0 ile başlayamaz');
