  const digits = [...str].map(Number);

  const oddSum = digits[0] + digits[2] + digits[4] + digits[6] + digits[8];
  const evenSum = digits[1] + digits[3] + digits[5] + digits[7];

  const tenthDigit = (((oddSum * 7 - evenSum) % 10) + 10) % 10;
  const eleventhDigit = digits.slice(0, 10).reduce((a, b) => a + b, 0) % 10;

  if (tenthDigit !== digits[9] || eleventhDigit !== digits[10]) {
    throw new Error('TC Kimlik No geçersiz');
  }

  return true;
}
