// GitHub sends the standard `retry-after` header in SECONDS (unlike some
// providers, e.g. Paraşüt, whose value is in ms — see #33m9), so we multiply
// by 1000. headers is a plain object with lower-case keys.
export function githubRetryDelayMs(headers) {
  const raw = headers && headers['retry-after'];
  if (raw === undefined || raw === null) return 60_000;
  const seconds = Number(raw);
  if (!Number.isFinite(seconds) || seconds <= 0) return 60_000;
  return Math.round(seconds * 1000);
