import { AppError } from './errors.js';

export default function validateTckn(s) {
  if (typeof s !== 'string' || !/^\d{11}$/.test(s)) {
    throw new AppError(
      'INVALID_TCKN',
      'HATA-INVALID_TCKN: geçersiz kimlik numarası'
    );
