  if (s[0] === '0') {
    throw new AppError(
      'INVALID_TCKN',
      'HATA-INVALID_TCKN: TCKN sıfır ile başlayamaz'
    );
  }

  const digits = s.split('').map(Number);

  // 10th digit check
  const oddSum = digits[0] + digits[2] + digits[4] + digits[6] + digits[8];
  const evenSum = digits[1] + digits[3] + digits[5] + digits[7];
  const calculated10 = (oddSum * 7 - evenSum) % 10;
  if (calculated10 !== digits[9]) {
    throw new AppError(
      'INVALID_TCKN',
      'HATA-INVALID_TCKN: geçersiz kimlik numarası'
    );
  }

  // 11th digit check
  const sumFirst10 = digits.slice(0, 10).reduce((a, b) => a + b, 0);
  const calculated11 = sumFirst10 % 10;
  if (calculated11 !== digits[10]) {
    throw new AppError(
      'INVALID_TCKN',
      'HATA-INVALID_TCKN: geçersiz kimlik numarası'
    );
  }

  return true;
}
