export function isAfterCutoff(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    throw new TypeError('isAfterCutoff expects a valid Date');
  }
  // Europe/Istanbul is UTC+3 with no DST; an order placed at or after
  // 17:00 local time misses same-day shipping.
  const istanbulHour = (date.getUTCHours() + 3) % 24;
  return istanbulHour >= 17;
}
