export function telefonNormalize(s) {
  if (typeof s !== 'string') return null;
  const digits = s.replace(/\D/g, '');
  if (!digits) return null;
  let num = digits;
  if (num.startsWith('90')) num = num.slice(2);
  else if (num.startsWith('0')) num = num.slice(1);
  if (!/^5\d{9}$/.test(num)) return null;
  return `+90${num}`;
}
