export default function parseKv(s) {
  const out = {};
  if (typeof s !== "string" || s.length === 0) return out;
  for (const segment of s.split(";")) {
    if (segment.length === 0) continue;
    const eq = segment.indexOf("=");
    if (eq === -1) {
      out[segment] = "";
    } else {
      out[segment.slice(0, eq)] = segment.slice(eq + 1);
    }
  }
  return out;
}
