```js
// invoiceVat(lineNets, ratePercent) → total KDV in kuruş
// Per decision #85j1: KDV is computed per invoice line in integer kuruş,
// each line rounded half-even (banker's rounding), then summed.
// lineNets are integer kuruş (Number is fine; BigInt handled). never float money.
export function invoiceVat(lineNets, ratePercent) {
  let total = 0n;
  for (const net of lineNets) {
    const amount = typeof net === 'bigint' ? net : BigInt(net);
    // (amount * ratePercent) / 100 in integer arithmetic, kuruş is the smallest unit.
    // The division is exact (both operands are integers), so no fractional kuruş —
    // a half-even round is only meaningful if a sub-kuruş unit existed.
    total += (amount * BigInt(ratePercent)) / 100n;
  }
  return Number(total);
}
