let featureFlagsModule;

try {
  featureFlagsModule = await import('./featureFlags.js');
} catch {
  try {
    featureFlagsModule = await import('./features.js');
  } catch {
    try {
      featureFlagsModule = await import('./feature-flags.js');
    } catch {
      featureFlagsModule = await import('./flags.js');
    }
  }
}

function isNewCheckoutEnabled() {
  const mod = featureFlagsModule;

  const fnCandidates = [
    mod.isFeatureEnabled,
    mod.default?.isFeatureEnabled,
    mod.default,
    mod.featureFlags,
    mod.features,
    mod.flags,
  ];

  for (const fn of fnCandidates) {
    if (typeof fn === 'function') {
      return fn('new checkout') === true;
    }
  }

  const flags =
    (mod.featureFlags && typeof mod.featureFlags !== 'function' ? mod.featureFlags : undefined) ??
    (mod.features && typeof mod.features !== 'function' ? mod.features : undefined) ??
    (mod.flags && typeof mod.flags !== 'function' ? mod.flags : undefined) ??
    (mod.default && typeof mod.default !== 'function' ? mod.default : undefined) ??
    mod;

  return flags?.['new checkout'] === true;
}

export function checkoutVersion() {
  return isNewCheckoutEnabled() ? 'v2' : 'v1';
}
