  if (!Number.isFinite(kuruş)) {
    throw new TypeError('formatTutar: tutar kuruş cinsinden sayısal bir değer olmalı');
  }

  const negative = kuruş < 0;
  const abs = Math.abs(Math.trunc(kuruş));

  const tl = Math.trunc(abs / 100);
  const kr = Math.abs(abs % 100);

  const tlStr = String(tl).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const krStr = String(kr).padStart(2, '0');

  return `${negative ? '-' : ''}${tlStr},${krStr} TL`;
