export function invoiceVat(lineNets, ratePercent) {
  let total = 0;
  for (const net of lineNets) {
    const value = net * ratePercent;
    const quotient = Math.trunc(value / 100);
    const remainder = value - quotient * 100;
    let lineVat;
    if (remainder < 50) {
      lineVat = quotient;
    } else if (remainder > 50) {
      lineVat = quotient + 1;
    } else {
      lineVat = quotient % 2 === 0 ? quotient : quotient + 1;
    }
    total += lineVat;
  }
  return total;
}
