import { AppError } from './errors.js';

const TCKN_DIGITS = /^\d{11}$/;

export function validateTckn(s) {
  const digits = String(s);

  if (!TCKN_DIGITS.test(digits)) {
    throw new AppError('INVALID_TCKN', 'HATA-TCKN: kimlik numarası 11 haneli rakamlardan oluşmalıdır');
  }

  if (digits[0] === '0') {
    throw new AppError('INVALID_TCKN', 'HATA-TCKN: kimlik numarası 0 ile başlayamaz');
  }

  const d = [...digits].map(Number);

  const oddSum = d[0] + d[2] + d[4] + d[6] + d[8];
  const evenSum = d[1] + d[3] + d[5] + d[7];
  const tenth = (oddSum * 7 - evenSum) % 10;

  const sumFirstTen = d.slice(0, 10).reduce((sum, n) => sum + n, 0);

  if (tenth !== d[9] || sumFirstTen % 10 !== d[10]) {
    throw new AppError('INVALID_TCKN', 'HATA-TCKN: geçersiz kimlik numarası');
  }

  return true;
}
