import { AppError } from './errors.js';

const INVALID_TCKN_MESSAGE = 'HATA-TCKN: geçersiz kimlik numarası';

export function validateTckn(s) {
  const value = String(s ?? '');

  if (!/^\d{11}$/.test(value)) {
    throw new AppError('INVALID_TCKN', INVALID_TCKN_MESSAGE);
  }

  if (value[0] === '0') {
    throw new AppError('INVALID_TCKN', INVALID_TCKN_MESSAGE);
  }

  const digits = value.split('').map(Number);
  const firstNineDigits = digits.slice(0, 9);

  const oddSum = firstNineDigits.reduce(
    (sum, digit, index) => (index % 2 === 0 ? sum + digit : sum),
    0,
  );
  const evenSum = firstNineDigits.reduce(
    (sum, digit, index) => (index % 2 === 1 ? sum + digit : sum),
    0,
  );

  const tenthDigit = (((oddSum * 7 - evenSum) % 10) + 10) % 10;
  const eleventhDigit =
    digits.slice(0, 10).reduce((sum, digit) => sum + digit, 0) % 10;

  if (digits[9] !== tenthDigit || digits[10] !== eleventhDigit) {
    throw new AppError('INVALID_TCKN', INVALID_TCKN_MESSAGE);
  }

  return true;
}
