/**
 * Kullanıcının girdiği telefon numarasını veritabanı formatına (E.164: +90 ile
 * başlar, boşluksuz, ör. +905321234567) çevirir.
 * Geçersiz girdi için null döner.
 *
 * @param {string} s - ör. "0532 123 45 67", "532-123-4567", "+90 532 123 45 67", "0090..."
 * @returns {string|null}
 */
export function telefonNormalize(s) {
  if (typeof s !== 'string') return null;

  let digits = s.replace(/\D/g, '');

  // Uluslararası erişim öneki (00) varsa at
  if (digits.startsWith('00')) {
    digits = digits.slice(2);
  }

  // +90 olmadan ülke koduyla girilmişse (90 + 10 hane) ülke kodunu ayır
  if (digits.length === 12 && digits.startsWith('90')) {
    digits = digits.slice(2);
  }

  // 10 haneli ulusal numara
  if (digits.length === 10) {
    return '+90' + digits;
  }

  // Başında 0 olan 11 haneli ulusal numara
  if (digits.length === 11 && digits.startsWith('0')) {
    return '+90' + digits.slice(1);
  }

  return null;
}
