export function databaseUrl() {
  const hasParts = [
    'PGHOST', 'PGPORT', 'PGDATABASE', 'PGUSER', 'PGPASSWORD',
    'DB_HOST', 'DB_PORT', 'DB_NAME', 'DB_USER', 'DB_PASSWORD',
    'POSTGRES_HOST', 'POSTGRES_PORT', 'POSTGRES_DB', 'POSTGRES_USER', 'POSTGRES_PASSWORD'
  ].some((key) => process.env[key] !== undefined && process.env[key] !== '');

  if (!hasParts && process.env.DATABASE_URL) {
    return process.env.DATABASE_URL;
  }

  const user = process.env.DB_USER || process.env.PGUSER || process.env.POSTGRES_USER || 'postgres';
  const password = process.env.DB_PASSWORD || process.env.PGPASSWORD || process.env.POSTGRES_PASSWORD || '';
  const host = process.env.DB_HOST || process.env.PGHOST || process.env.POSTGRES_HOST || 'localhost';
  const port = process.env.DB_PORT || process.env.PGPORT || process.env.POSTGRES_PORT || '5432';
  const database = process.env.DB_NAME || process.env.PGDATABASE || process.env.POSTGRES_DB || 'postgres';

  const credentials = password
    ? `${encodeURIComponent(user)}:${encodeURIComponent(password)}@`
    : `${encodeURIComponent(user)}@`;

  const url = `postgres://${credentials}${host}:${port}/${encodeURIComponent(database)}`;
  process.env.DATABASE_URL = url;
  return url;
}

export default databaseUrl;
