import { AppError } from './errors.js';

/**
 * Validates a Turkish Republic ID number (TC Kimlik No).
 * @param {string|number} s - The TCKN to validate.
 * @returns {true} if valid.
 * @throws {AppError} with code INVALID_TCKN if validation fails.
 */
export function validateTckn(s) {
  const str = String(s);

  // Must be exactly 11 digits
  if (!/^\d{11}$/.test(str)) {
    throw new AppError('INVALID_TCKN', 'HATA-TCKN: 11 haneli olmalıdır');
  }

  // First digit cannot be 0
  if (str[0] === '0') {
    throw new AppError('INVALID_TCKN', 'HATA-TCKN: 0 ile başlayamaz');
  }

  const digits = str.split('').map(Number);

  // Algorithm: 10th digit = (sum of odd positions * 7 - sum of even positions) mod 10
  const oddSum = digits[0] + digits[2] + digits[4] + digits[6] + digits[8];
  const evenSum = digits[1] + digits[3] + digits[5] + digits[7];
  const tenthDigit = (oddSum * 7 - evenSum) % 10;

  // 11th digit = sum of first 10 digits mod 10
  const eleventhDigit = digits.slice(0, 10).reduce((a, b) => a + b, 0) % 10;

  if (tenthDigit !== digits[9] || eleventhDigit !== digits[10]) {
    throw new AppError('INVALID_TCKN', 'HATA-TCKN: geçersiz kimlik numarası');
  }

  return true;
}
```

