 * per line, as required by accounting.
 *
 * @param {bigint[]|number[]} lineNets – each line net amount in kuruş (integer)
 * @param {number} ratePercent – VAT rate as a percentage (e.g. 20 for 20%)
 * @returns {bigint} total VAT in kuruş
 */
export function invoiceVat(lineNets, ratePercent) {
  const rate = BigInt(ratePercent);
  const denominator = 100n;
  let total = 0n;

  for (const net of lineNets) {
    const numerator = BigInt(net) * rate;
    const vat = roundHalfEven(numerator, denominator);
    total += vat;
  }

  return total;
}

/**
 * Banker's rounding (half‑even) for bigint division.
 * @param {bigint} numerator
 * @param {bigint} denominator – must be positive
 * @returns {bigint} rounded quotient
 */
function roundHalfEven(numerator, denominator) {
  const quotient = numerator / denominator;
  const remainder = numerator % denominator;

  if (remainder === 0n) return quotient;

  const twoRem = remainder * 2n;
  if (twoRem < denominator) return quotient;
  if (twoRem > denominator) return quotient + 1n;

  // half case: round to even quotient
  return quotient % 2n === 0n ? quotient : quotient + 1n;
}
