export function addIndexMigration(table, column) {
  const indexName = `idx_${table}_${column}`.toLowerCase();
  const sql = `
DO $$
DECLARE
  retries int := 0;
  max_retries int := 5;
  success boolean := false;
BEGIN
  WHILE retries < max_retries AND NOT success LOOP
    BEGIN
      SET LOCAL lock_timeout = '2s';
      EXECUTE 'CREATE INDEX CONCURRENTLY "' || '${indexName}' || '" ON "' || '${table}' || '" ("' || '${column}' || '")';
      success := true;
    EXCEPTION
      WHEN deadlock_detected THEN
        retries := retries + 1;
        IF retries < max_retries THEN
          PERFORM pg_sleep(1);
        ELSE
          RAISE;
        END IF;
    END;
  END LOOP;
END;
$$;
`;
  return [sql];
}
