function convertBigInts(value) {
  if (typeof value === 'bigint') {
    const s = value.toString();
    if (s.length === 0) return '0.00';
    if (s.length === 1) return `0.0${s}`;
    if (s.length === 2) return `0.${s}`;
    const intPart = s.slice(0, -2);
    const fracPart = s.slice(-2);
    return `${intPart}.${fracPart}`;
  }
  if (Array.isArray(value)) {
    return value.map(convertBigInts);
  }
  if (value && typeof value === 'object') {
    const obj = {};
    for (const [k, v] of Object.entries(value)) {
      obj[k] = convertBigInts(v);
    }
    return obj;
  }
  return value;
}

export default function orderToJson(order) {
  return JSON.stringify(convertBigInts(order));
}
