```js
/**
 * Calculates the retry delay in milliseconds after a 429 response from Paraşüt API.
 * Uses Retry-After or X-Rate-Limit-Reset headers if present, falling back to a default delay.
 *
 * @param {Record<string, string | number>} headers
 * @returns {number} Delay in milliseconds
 */
export function parasutRetryDelayMs(headers = {}) {
  const DEFAULT_DELAY_MS = 60000;

  const retryAfter = headers['retry-after'];
  if (retryAfter !== undefined && retryAfter !== null) {
    const parsed = Number(retryAfter);
    if (!Number.isNaN(parsed) && parsed >= 0) {
      return parsed * 1000;
    }

    const dateParsed = Date.parse(String(retryAfter));
    if (!Number.isNaN(dateParsed)) {
      return Math.max(0, dateParsed - Date.now());
    }
  }

  const rateLimitReset = headers['x-rate-limit-reset'] ?? headers['x-ratelimit-reset'];
  if (rateLimitReset !== undefined && rateLimitReset !== null) {
    const resetTime = Number(rateLimitReset);
    if (!Number.isNaN(resetTime)) {
      // If the reset timestamp is in seconds (standard Unix timestamp)
      if (resetTime > 1e11) {
        return Math.max(0, resetTime - Date.now());
      }
      if (resetTime > 1e8) {
        return Math.max(0, resetTime * 1000 - Date.now());
      }
      return resetTime * 1000;
    }
  }

  return DEFAULT_DELAY_MS;
}
