const DEFAULT_DELAY_MS = 60000;

/**
 * Calculates how many milliseconds to wait after a 429 response from the Paraşüt API.
 * Paraşüt provides rate limiting headers such as `x-rate-limit-reset` or standard `retry-after`.
 *
 * @param {Record<string, string | number | undefined>} headers Plain headers object (lower-case keys)
 * @returns {number} Milliseconds to wait before retrying
 */
export function parasutRetryDelayMs(headers = {}) {
  // Check standard Retry-After header first (can be seconds or an HTTP-date)
  const retryAfter = headers['retry-after'];
  if (retryAfter !== undefined && retryAfter !== null) {
    const seconds = Number(retryAfter);
    if (!Number.isNaN(seconds) && seconds >= 0) {
      return Math.ceil(seconds * 1000);
    }

    const dateMs = Date.parse(String(retryAfter));
    if (!Number.isNaN(dateMs)) {
      const delay = dateMs - Date.now();
      return Math.max(0, delay);
    }
  }

  // Check Paraşüt rate limit reset headers (x-rate-limit-reset or x-ratelimit-reset)
  // Usually Unix timestamp in seconds or remaining seconds
  const resetHeader = headers['x-rate-limit-reset'] ?? headers['x-ratelimit-reset'];
  if (resetHeader !== undefined && resetHeader !== null) {
    const resetVal = Number(resetHeader);
    if (!Number.isNaN(resetVal) && resetVal >= 0) {
      // If epoch timestamp in seconds (greater than ~year 2001)
      if (resetVal > 1000000000) {
        const delay = resetVal * 1000 - Date.now();
        return Math.max(0, Math.ceil(delay));
      }
      // Otherwise interpreted as delta seconds
      return Math.ceil(resetVal * 1000);
    }
  }

  return DEFAULT_DELAY_MS;
}
