```js
import { TIMEZONE } from './config.js';

/**
 * Parses a "YYYY-MM-DD" date-only string into a Date representing that day in the business timezone.
 *
 * @param {string} s - Date string in "YYYY-MM-DD" format.
 * @returns {Date}
 */
export function parseDeliveryDate(s) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!match) {
    throw new Error(`Invalid date format: ${s}`);
  }

  const [, year, month, day] = match;
  const targetYear = Number(year);
  const targetMonth = Number(month);
  const targetDay = Number(day);

  // Initial estimate in UTC
  let utcTime = Date.UTC(targetYear, targetMonth - 1, targetDay, 0, 0, 0, 0);

  const getParts = (d) => {
    const formatter = new Intl.DateTimeFormat('en-US', {
      timeZone: TIMEZONE,
      year: 'numeric',
      month: 'numeric',
      day: 'numeric',
      hour: 'numeric',
      minute: 'numeric',
      second: 'numeric',
      hour12: false,
    });
    const parts = formatter.formatToParts(d);
    const map = {};
    for (const p of parts) {
      map[p.type] = p.value;
    }
    const h = Number(map.hour === '24' ? '0' : map.hour);
    return {
      year: Number(map.year),
      month: Number(map.month),
      day: Number(map.day),
      hour: h,
      minute: Number(map.minute),
      second: Number(map.second),
    };
  };

  // Adjust estimate to match midnight in the specified timezone
  for (let i = 0; i < 3; i++) {
    const d = new Date(utcTime);
    const parts = getParts(d);

    const diffDays =
      (Date.UTC(parts.year, parts.month - 1, parts.day) -
        Date.UTC(targetYear, targetMonth - 1, targetDay)) /
      86400000;
    const diffMs =
      diffDays * 86400000 +
      parts.hour * 3600000 +
      parts.minute * 60000 +
      parts.second * 1000;

    if (diffMs === 0) break;
    utcTime -= diffMs;
  }

  return new Date(utcTime);
}
