const TIMEZONE = process.env.BUSINESS_TIMEZONE || 'UTC';

/**
 * Parses a date-only string (YYYY-MM-DD) into a Date representing that day in the business timezone.
 *
 * @param {string} s - Date string in YYYY-MM-DD format
 * @returns {Date}
 */
export function parseDeliveryDate(s) {
  if (!s || typeof s !== 'string') {
    throw new TypeError('Expected a date string in YYYY-MM-DD format');
  }

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s.trim());
  if (!match) {
    throw new RangeError(`Invalid date format: "${s}". Expected YYYY-MM-DD.`);
  }

  const [, yearStr, monthStr, dayStr] = match;
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);

  // Validate calendar bounds
  const utcDate = new Date(Date.UTC(year, month - 1, day));
  if (
    utcDate.getUTCFullYear() !== year ||
    utcDate.getUTCMonth() !== month - 1 ||
    utcDate.getUTCDate() !== day
  ) {
    throw new RangeError(`Invalid calendar date: "${s}"`);
  }

  // Find the exact UTC instant corresponding to midnight in the target timezone
  let guess = new Date(Date.UTC(year, month - 1, day, 0, 0, 0));
  for (let i = 0; i < 3; i++) {
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: TIMEZONE,
      year: 'numeric',
      month: 'numeric',
      day: 'numeric',
      hour: 'numeric',
      minute: 'numeric',
      second: 'numeric',
      hour12: false
    }).formatToParts(guess);

    const map = {};
    for (const { type, value } of parts) {
      map[type] = value;
    }

    const tzHour = map.hour === '24' ? 0 : Number(map.hour);
    const tzYear = Number(map.year);
    const tzMonth = Number(map.month);
    const tzDay = Number(map.day);
    const tzMinute = Number(map.minute);
    const tzSecond = Number(map.second);

    const tzAsUtc = Date.UTC(tzYear, tzMonth - 1, tzDay, tzHour, tzMinute, tzSecond);
    const targetAsUtc = Date.UTC(year, month - 1, day, 0, 0, 0);
    const diff = targetAsUtc - tzAsUtc;

    if (diff === 0) {
      break;
    }
    guess = new Date(guess.getTime() + diff);
  }

  return guess;
}
