/**
 * Calculates milliseconds to wait before retrying a request after receiving
 * a 429 Too Many Requests response from the Paraşüt API.
 *
 * @param {Record<string, string | undefined>} [headers={}]
 * @returns {number} Delay in milliseconds
 */
export function parasutRetryDelayMs(headers = {}) {
  const retryAfter = headers['retry-after'];
  if (retryAfter !== undefined && retryAfter !== null && retryAfter !== '') {
    const seconds = Number(retryAfter);
    if (!Number.isNaN(seconds)) {
      return Math.max(0, Math.ceil(seconds * 1000));
    }

    const dateMs = Date.parse(retryAfter);
    if (!Number.isNaN(dateMs)) {
      return Math.max(0, dateMs - Date.now());
    }
  }

  const rateLimitReset = headers['x-ratelimit-reset'] ?? headers['x-rate-limit-reset'];
  if (rateLimitReset !== undefined && rateLimitReset !== null && rateLimitReset !== '') {
    const resetNum = Number(rateLimitReset);
    if (!Number.isNaN(resetNum)) {
      // If epoch timestamp in seconds
      if (resetNum > 1e9 && resetNum < 1e12) {
        return Math.max(0, resetNum * 1000 - Date.now());
      }
      // If epoch timestamp in milliseconds
      if (resetNum >= 1e12) {
        return Math.max(0, resetNum - Date.now());
      }
      // If delta in seconds
      return Math.max(0, Math.ceil(resetNum * 1000));
    }
