const TIMEZONE = 'Europe/Istanbul';

/**
 * Parses a "YYYY-MM-DD" delivery date string into a Date object representing
 * the start of that day (00:00:00) in the business timezone.
 *
 * @param {string} s - Date string in YYYY-MM-DD format
 * @returns {Date} Date instance corresponding to the start of that day in the business timezone
 */
export function parseDeliveryDate(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Expected date string');
  }

  const match = s.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) {
    throw new Error(`Invalid delivery date format: "${s}". Expected YYYY-MM-DD.`);
  }

  const [, year, month, day] = match;

  // Determine timezone offset for the given local date in the target timezone
  const utcGuess = new Date(Date.UTC(+year, +month - 1, +day, 0, 0, 0));
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: TIMEZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });

  const parts = Object.fromEntries(
    dtf.formatToParts(utcGuess).map(p => [p.type, p.value])
  );

  const localInTzAsUtc = Date.UTC(
    +parts.year,
    +parts.month - 1,
    +parts.day,
    +parts.hour === 24 ? 0 : +parts.hour,
    +parts.minute,
    +parts.second
  );

  const offsetMs = localInTzAsUtc - utcGuess.getTime();
  return new Date(utcGuess.getTime() - offsetMs);
}
