  }

  const resetTime = headers['x-rate-limit-reset'] ?? headers['x-ratelimit-reset'];
  if (resetTime !== undefined && resetTime !== null) {
    const resetNumeric = Number(resetTime);
    if (!Number.isNaN(resetNumeric) && resetNumeric >= 0) {
      if (resetNumeric > 1000000000000) {
        const diff = resetNumeric - Date.now();
        return diff > 0 ? diff : 0;
