/**
 * Parses a date-only string (YYYY-MM-DD) from the delivery form into a local Date.
 *
 * Using new Date("YYYY-MM-DD") parses the string as UTC midnight, which shifts
 * back to the previous calendar day when displayed or formatted in timezones west of UTC.
 * Parsing year, month, and day explicitly constructs the date in the local runtime timezone.
 *
 * @param {string} s - Date string in YYYY-MM-DD format
 * @returns {Date}
 */
export function parseDeliveryDate(s) {
  if (!s || typeof s !== 'string') {
    throw new TypeError('Expected a date string in YYYY-MM-DD format');
  }

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s.trim());
  if (!match) {
    throw new RangeError(`Invalid date format: "${s}". Expected YYYY-MM-DD.`);
  }

  const [, yearStr, monthStr, dayStr] = match;
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);

  const date = new Date(year, month - 1, day);

  if (
    date.getFullYear() !== year ||
    date.getMonth() !== month - 1 ||
    date.getDate() !== day
  ) {
    throw new RangeError(`Invalid calendar date: "${s}"`);
  }

  return date;
}
