      // If epoch timestamp in seconds
      if (resetNum > 1e9 && resetNum < 1e12) {
        return Math.max(0, resetNum * 1000 - Date.now());
      }
      // If epoch timestamp in milliseconds
      if (resetNum >= 1e12) {
