import { BUSINESS_TIMEZONE } from './config.js';

/**
 * Parses a date-only string (e.g. "2026-03-01") into a Date
 * representing the start of that day in the business timezone.
 *
 * @param {string} s - Date-only string in YYYY-MM-DD format.
 * @returns {Date}
 */
export function parseDeliveryDate(s) {
  const [year, month, day] = s.split('-').map(Number);
  const tz = BUSINESS_TIMEZONE || 'UTC';

  // Guess UTC midnight for the given date
  const guess = new Date(Date.UTC(year, month - 1, day, 0, 0, 0));

  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: 'numeric',
    second: 'numeric',
    hour12: false,
  });

  const parts = dtf.formatToParts(guess);
  const p = {};
  for (const part of parts) {
    p[part.type] = part.value;
  }

  const tzHours = parseInt(p.hour, 10) === 24 ? 0 : parseInt(p.hour, 10);
  const tzDay = parseInt(p.day, 10);
  const tzMonth = parseInt(p.month, 10);
  const tzYear = parseInt(p.year, 10);

  const asUtc = Date.UTC(tzYear, tzMonth - 1, tzDay, tzHours, parseInt(p.minute, 10), parseInt(p.second, 10));
  const offset = asUtc - guess.getTime();

  return new Date(Date.UTC(year, month - 1, day, 0, 0, 0) - offset);
}
