const DEFAULT_DELAY_MS = 60000;

/**
 * Calculates how many milliseconds to wait after a 429 response from the Paraşüt API.
 * Paraşüt provides Retry-After / X-RateLimit-Reset as an integer representing either:
 * - milliseconds when the value is large (e.g. 1500 ms)
 * - seconds / unix epoch timestamp
 *
 * @param {Record<string, string>} [headers={}]
 * @returns {number} Delay in milliseconds
 */
export function parasutRetryDelayMs(headers = {}) {
  const parseRawValue = (val) => {
    if (val === undefined || val === null) {
      return null;
    }

    const num = Number(val);
    if (!Number.isNaN(num) && num >= 0) {
      // Unix timestamp in seconds (e.g. > 1_000_000_000)
      if (num > 1e9) {
        return Math.max(0, Math.ceil(num * 1000 - Date.now()));
      }
      // Paraşüt rate limit reset intervals are within short windows (per-minute or per-second).
      // Values > 120 in this context represent milliseconds (e.g. 1500 -> 1.5s),
      // whereas smaller values represent seconds (e.g. 15 -> 15s).
      if (num > 120) {
        return Math.ceil(num);
      }
      return Math.ceil(num * 1000);
    }

    const dateMs = Date.parse(val);
    if (!Number.isNaN(dateMs)) {
      return Math.max(0, Math.ceil(dateMs - Date.now()));
    }

    return null;
  };

  const retryAfter = headers['retry-after'];
  const delayFromRetryAfter = parseRawValue(retryAfter);
  if (delayFromRetryAfter !== null) {
    return delayFromRetryAfter;
  }

  const rateLimitReset = headers['x-ratelimit-reset'] ?? headers['x-rate-limit-reset'];
  const delayFromReset = parseRawValue(rateLimitReset);
  if (delayFromReset !== null) {
    return delayFromReset;
  }

  return DEFAULT_DELAY_MS;
}
