import { BUSINESS_TIMEZONE } from './timezone.js';

/**
 * Returns the UTC offset in minutes for a given timezone at a specific UTC instant.
 *
 * @param {string} timeZone
 * @param {Date} date
 * @returns {number} Offset in minutes (e.g. -300 for UTC-5)
 */
function getTimezoneOffset(timeZone, date) {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23',
  });

  const parts = dtf.formatToParts(date);
  const partMap = {};
  for (const part of parts) {
    partMap[part.type] = part.value;
  }

  const asUtc = Date.UTC(
    Number(partMap.year),
    Number(partMap.month) - 1,
    Number(partMap.day),
    Number(partMap.hour),
    Number(partMap.minute),
    Number(partMap.second)
  );

  return (asUtc - date.getTime()) / 60000;
}

/**
 * Parses a date-only string like "2026-03-01" into a Date
 * representing the start of that day in the business timezone.
 *
 * @param {string} s - Date-only string in YYYY-MM-DD format.
 * @returns {Date}
 */
export function parseDeliveryDate(s) {
  const [yearStr, monthStr, dayStr] = s.split('-');
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);

  const tz = BUSINESS_TIMEZONE;
  const targetUtcEstimate = Date.UTC(year, month - 1, day, 0, 0, 0);
  const offset = getTimezoneOffset(tz, new Date(targetUtcEstimate));
  const candidateUtc = targetUtcEstimate - offset * 60000;
  const offsetRefined = getTimezoneOffset(tz, new Date(candidateUtc));

  return new Date(targetUtcEstimate - offsetRefined * 60000);
}
