/**
 * Parses a date-only string (e.g. "2026-03-01") into a Date representing
 * midnight on that date in the local/business timezone.
 *
 * @param {string} s - Date string in YYYY-MM-DD format
 * @returns {Date} Date object for that day
 */
export function parseDeliveryDate(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Expected date string');
  }

  const match = s.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) {
    throw new Error(`Invalid delivery date format: "${s}". Expected YYYY-MM-DD.`);
  }

  const [, yearStr, monthStr, dayStr] = match;
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);

  const date = new Date(year, month - 1, day);

  if (
    date.getFullYear() !== year ||
    date.getMonth() !== month - 1 ||
    date.getDate() !== day
  ) {
    throw new Error(`Invalid calendar date: "${s}"`);
  }

  return date;
}
