/**
 * Calculates the retry delay in milliseconds after receiving a 429 response
 * from the Paraşüt API based on response headers.
 *
 * @param {Record<string, string | undefined>} headers
 * @returns {number} Delay in milliseconds
 */
export function parasutRetryDelayMs(headers) {
  if (!headers) {
    return 1000;
  }

  const retryAfter = headers['retry-after'];
  if (retryAfter) {
    const seconds = Number(retryAfter);
    if (!Number.isNaN(seconds)) {
      return Math.max(0, seconds * 1000);
    }
    const dateMs = Date.parse(retryAfter);
    if (!Number.isNaN(dateMs)) {
      return Math.max(0, dateMs - Date.now());
    }
  }

  const reset = headers['x-ratelimit-reset'];
  if (reset) {
    const resetNum = Number(reset);
    if (!Number.isNaN(resetNum)) {
      // If epoch timestamp in seconds vs relative delta
      if (resetNum > 1e9) {
        return Math.max(0, resetNum * 1000 - Date.now());
      }
      return Math.max(0, resetNum * 1000);
    }
  }

  return 1000;
}

export default parasutRetryDelayMs;
