```js
import { TIMEZONE } from './config.js';

/**
 * Parses a date-only string (e.g. "YYYY-MM-DD") into a Date object
 * representing midnight at the start of that day in the business timezone.
 *
 * @param {string} s - Date-only string in YYYY-MM-DD format
 * @returns {Date} Date instance corresponding to the start of the specified day in the business timezone
 */
export function parseDeliveryDate(s) {
  const [yearStr, monthStr, dayStr] = s.split('-');
  const year = parseInt(yearStr, 10);
  const month = parseInt(monthStr, 10);
  const day = parseInt(dayStr, 10);

  // Guess UTC midnight for the given date components
  let utcTime = Date.UTC(year, month - 1, day);

  const getTzOffset = (time) => {
    const formatter = new Intl.DateTimeFormat('en-US', {
      timeZone: TIMEZONE,
      year: 'numeric',
      month: 'numeric',
      day: 'numeric',
      hour: 'numeric',
      minute: 'numeric',
      second: 'numeric',
      hourCycle: 'h23',
    });

    const parts = formatter.formatToParts(new Date(time));
    const partMap = {};
    for (const { type, value } of parts) {
      partMap[type] = parseInt(value, 10);
    }

    const asUtc = Date.UTC(
      partMap.year,
      partMap.month - 1,
      partMap.day,
      partMap.hour,
      partMap.minute,
      partMap.second
    );

    return asUtc - time;
  };

  // Adjust UTC time by timezone offset
  const offset1 = getTzOffset(utcTime);
  let targetTime = utcTime - offset1;

  // Re-check offset at target time in case of DST transitions
  const offset2 = getTzOffset(targetTime);
  if (offset1 !== offset2) {
    targetTime = utcTime - offset2;
  }

  return new Date(targetTime);
}
