/**
 * Calculates the retry delay in milliseconds after receiving a 429 response
 * from the Paraşüt API.
 *
 * @param {Record<string, string | number | undefined>} headers - Response headers with lowercase keys
 * @returns {number} Milliseconds to wait before retrying
 */
export function parasutRetryDelayMs(headers = {}) {
  const DEFAULT_DELAY_MS = 60000;

  const retryAfter = headers['retry-after'];
  if (retryAfter !== undefined && retryAfter !== null && retryAfter !== '') {
    const parsed = Number(retryAfter);
    if (!Number.isNaN(parsed) && parsed >= 0) {
      return parsed * 1000;
    }

    const dateParsed = Date.parse(String(retryAfter));
    if (!Number.isNaN(dateParsed)) {
      const diff = dateParsed - Date.now();
      return diff > 0 ? diff : 0;
    }
  }

  const rateLimitReset = headers['x-ratelimit-reset'];
  if (rateLimitReset !== undefined && rateLimitReset !== null && rateLimitReset !== '') {
    const resetTime = Number(rateLimitReset);
    if (!Number.isNaN(resetTime) && resetTime > 0) {
      // If unix timestamp (seconds vs milliseconds)
      const targetMs = resetTime > 1e11 ? resetTime : resetTime * 1000;
      const diff = targetMs - Date.now();
      return diff > 0 ? diff : 0;
    }
  }

  return DEFAULT_DELAY_MS;
}
