/**
 * Calculates retry delay in milliseconds from Paraşüt 429 response headers.
 * Note: Paraşüt returns `Retry-After` already expressed in milliseconds
 * (e.g. 1500 for 1.5 seconds), not seconds.
 *
 * @param {Record<string, string | undefined>} headers - Lower-case header key-value map.
 * @returns {number} Milliseconds to wait before retrying.
 */
export function parasutRetryDelayMs(headers = {}) {
  const retryAfter = headers['retry-after'];
  if (retryAfter !== undefined) {
    const numeric = Number(retryAfter);
    if (!Number.isNaN(numeric) && numeric >= 0) {
      return Math.ceil(numeric);
    }
    const httpDate = Date.parse(retryAfter);
    if (!Number.isNaN(httpDate)) {
      return Math.max(0, httpDate - Date.now());
    }
  }

  const rateLimitReset = headers['x-ratelimit-reset'];
  if (rateLimitReset !== undefined) {
    const resetVal = Number(rateLimitReset);
    if (!Number.isNaN(resetVal) && resetVal > 0) {
      const resetMs = resetVal > 1e11 ? resetVal : resetVal * 1000;
      return Math.max(0, Math.ceil(resetMs - Date.now()));
    }
  }

  return 1000;
}
