 * Paraşüt provides the Retry-After header directly in milliseconds.
 *
 * @param {Record<string, string | undefined>} [headers] - Plain headers object with lower-case keys.
 * @returns {number} Delay in milliseconds.
 */
export function parasutRetryDelayMs(headers) {
  if (!headers) {
    return 1000;
  }

  const retryAfter = headers['retry-after'];
  if (retryAfter !== undefined && retryAfter !== null) {
    const ms = Number(retryAfter);
    if (!Number.isNaN(ms)) {
      return Math.max(0, Math.ceil(ms));
    }
    const dateMs = Date.parse(String(retryAfter));
    if (!Number.isNaN(dateMs)) {
      return Math.max(0, dateMs - Date.now());
    }
  }

  const resetHeader = headers['x-ratelimit-reset'] ?? headers['x-rate-limit-reset'];
  if (resetHeader !== undefined && resetHeader !== null) {
    const reset = Number(resetHeader);
    if (!Number.isNaN(reset)) {
      if (reset > 1e11) {
        return Math.max(0, Math.ceil(reset - Date.now()));
      }
      if (reset > 1e9) {
        return Math.max(0, Math.ceil(reset * 1000 - Date.now()));
      }
      return Math.max(0, Math.ceil(reset));
    }
  }

  return 1000;
}
