import config from './config.js';

const TIMEZONE = config?.TIMEZONE ?? config?.timezone ?? 'America/New_York';

export function parseDeliveryDate(s) {
  const [year, month, day] = s.split('-').map(Number);

  let guess = Date.UTC(year, month - 1, day, 12, 0, 0);

  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: TIMEZONE,
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: 'numeric',
    second: 'numeric',
    hourCycle: 'h23',
  });

  const getParts = (timestamp) => {
    const parts = dtf.formatToParts(new Date(timestamp));
    const obj = {};
    for (const { type, value } of parts) {
      if (type !== 'literal') obj[type] = Number(value);
    }
    return obj;
  };

  for (let i = 0; i < 3; i++) {
    const parts = getParts(guess);
    const tzAsUtc = Date.UTC(
      parts.year,
      parts.month - 1,
      parts.day,
      parts.hour,
      parts.minute,
      parts.second
    );
    const targetAsUtc = Date.UTC(year, month - 1, day, 0, 0, 0);
    const diff = targetAsUtc - tzAsUtc;
    if (diff === 0) break;
    guess += diff;
  }

  return new Date(guess);
}
