/**
 * Calculates the delay in milliseconds to wait before retrying after a 429 response
 * from the Paraşüt API based on response headers.
 *
 * Paraşüt API provides Retry-After in milliseconds rather than standard seconds.
 *
 * @param {Record<string, string | number | undefined>} headers - Plain headers object with lower-case keys.
 * @returns {number} Milliseconds to wait.
 */
export function parasutRetryDelayMs(headers = {}) {
  const retryAfter = headers['retry-after'];
  if (retryAfter !== undefined && retryAfter !== null && retryAfter !== '') {
    const numeric = Number(retryAfter);
    if (!Number.isNaN(numeric)) {
      return Math.max(0, Math.ceil(numeric));
    }
    const dateParsed = Date.parse(String(retryAfter));
    if (!Number.isNaN(dateParsed)) {
      return Math.max(0, dateParsed - Date.now());
    }
  }

  const resetHeader = headers['x-ratelimit-reset'] ?? headers['x-rate-limit-reset'];
  if (resetHeader !== undefined && resetHeader !== null && resetHeader !== '') {
    const resetNum = Number(resetHeader);
    if (!Number.isNaN(resetNum)) {
      if (resetNum > 1e11) {
        // Unix timestamp in milliseconds
        return Math.max(0, Math.ceil(resetNum - Date.now()));
      }
      if (resetNum > 1e9) {
        // Unix timestamp in seconds
        return Math.max(0, Math.ceil(resetNum * 1000 - Date.now()));
      }
      // Delta in milliseconds
      return Math.max(0, Math.ceil(resetNum));
    }
  }

  return 1000;
}
