/**
 * Parses a date-only string (e.g. "2026-03-01") into a Date representing
 * midnight of that day in the business timezone (Europe/Istanbul, UTC+03:00).
 *
 * @param {string} s - Date string in YYYY-MM-DD format
 * @returns {Date}
 */
export function parseDeliveryDate(s) {
  if (typeof s !== 'string') {
    throw new TypeError('Expected a string');
  }

  const trimmed = s.trim();
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(trimmed);
  if (!match) {
    throw new Error(`Invalid date format: "${s}". Expected YYYY-MM-DD.`);
  }

  const [, yearStr, monthStr, dayStr] = match;
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);

  const date = new Date(`${trimmed}T00:00:00+03:00`);

  if (Number.isNaN(date.getTime())) {
    throw new Error(`Invalid calendar date: "${s}".`);
  }

  // Validate calendar roll-over (e.g., February 31st)
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Istanbul',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });
  const formatted = formatter.format(date);
  if (formatted !== `${yearStr}-${monthStr}-${dayStr}`) {
    throw new Error(`Invalid calendar date: "${s}".`);
  }

  return date;
}
