  }

  // Validate calendar components using UTC arithmetic against the fixed +03:00 offset
  const utcOffsetMinutes = 3 * 60;
  const shiftedDate = new Date(date.getTime() + utcOffsetMinutes * 60 * 1000);
  if (
    shiftedDate.getUTCFullYear() !== year ||
    shiftedDate.getUTCMonth() !== month - 1 ||
    shiftedDate.getUTCDate() !== day
  ) {
    throw new Error(`Invalid calendar date: "${s}"`);
